window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"蛛网膜下腔出血脑脊液特点是？","options":["黄变仅见于晚期（早期血性）","清亮","毛玻璃样","均匀一致血性脑脊液"],"answer":3,"explanation":"蛛网膜下腔出血脑脊液均匀血性、压力增高，数日后可黄变。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2001","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"视乳头水肿提示？","options":["青光眼早期","视神经萎缩","颅内压增高","高血压仅眼底动脉硬化"],"answer":2,"explanation":"视乳头水肿是颅内压增高的重要客观体征，伴视力一般无明显下降（早期）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2002","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"瞳孔对光反射消失提示？","options":["视神经萎缩（必然）","中脑或动眼神经损害（危重）","正常变异","仅结膜炎"],"answer":1,"explanation":"对光反射消失提示中脑损害或动眼神经麻痹，是判断昏迷深度和脑死亡的重要指标。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2003","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"双侧瞳孔针尖样缩小提示？","options":["癫痫发作","脑疝（单侧散大）","阿托品中毒","脑桥出血或吗啡、有机磷中毒"],"answer":3,"explanation":"针尖样瞳孔见于脑桥出血、吗啡类和有机磷中毒；单侧散大固定提示小脑幕切迹疝。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2004","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"单侧瞳孔散大、对光反射消失提示？","options":["糖尿病昏迷","脑桥出血","吗啡中毒","小脑幕切迹疝"],"answer":3,"explanation":"单侧瞳孔散大为颞叶钩回疝（小脑幕切迹疝）压迫动眼神经所致，需紧急降颅压。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2005","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"体格检查的基本方法包括？","options":["影像检查","问诊、查体、化验","望闻问切","视诊、触诊、叩诊、听诊、嗅诊"],"answer":3,"explanation":"体格检查五法：视、触、叩、听、嗅。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2006","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"深部触诊法主要用于检查？","options":["腹腔脏器和深部包块","皮肤温度","脉搏","浅表淋巴结"],"answer":0,"explanation":"深部触诊（深部滑行、双手、深压、冲击触诊）用于腹腔深部病变。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2007","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"叩诊呈鼓音见于？","options":["气胸（过清音或鼓音）","大量胸腔积液","肺实变","胃泡区和肠胀气"],"answer":3,"explanation":"鼓音见于含大量气体的空腔器官（胃泡、肠胀气）；肺实变呈浊音。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2008","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺实变的叩诊音是？","options":["过清音","鼓音","浊音或实音","清音"],"answer":2,"explanation":"肺实变（肺炎、肺不张）叩诊呈浊音或实音，语颤增强、病理性支气管呼吸音。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2009","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺气肿的叩诊音是？","options":["鼓音","浊音","实音","过清音"],"answer":3,"explanation":"肺气肿肺含气增多、弹性减弱，叩诊呈过清音，肺下界下移。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2010","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常肺部叩诊音是？","options":["鼓音","清音","浊音","过清音"],"answer":1,"explanation":"正常肺组织叩诊为清音；肝浊音界消失（鼓音）提示气腹或胃肠穿孔。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2011","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"湿啰音的特点是？","options":["与体位无关","呼气末明显、多变","干啰音的一种","吸气末明显、部位较固定、咳嗽后可消失或变化"],"answer":3,"explanation":"湿啰音（水泡音）为气道内液体经气流形成，吸气末明显，咳嗽后可变化。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2012","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"干啰音的特点是？","options":["仅见于胸腔积液","吸气末明显","固定不变","呼气相明显、部位多变、咳嗽后可消失"],"answer":3,"explanation":"干啰音由支气管狭窄产生，呼气明显、易变，哮鸣音为其典型。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2013","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"哮鸣音提示？","options":["肺实变","肺水肿","胸腔积液","支气管痉挛狭窄（哮喘）"],"answer":3,"explanation":"哮鸣音为高调干啰音，提示支气管痉挛狭窄，是哮喘的典型体征。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2014","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸腔积液体征不包括？","options":["呼吸音减弱","患侧叩诊浊音","气管向健侧移位","患侧呼吸音增强"],"answer":3,"explanation":"胸腔积液患侧呼吸音减弱或消失，不会增强。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2015","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气胸的体征是？","options":["患侧叩诊浊音","患侧叩诊鼓音、呼吸音减弱","气管向患侧移位","双肺满布湿啰音"],"answer":1,"explanation":"气胸患侧胸廓饱满、叩诊鼓音、呼吸音减弱，气管移向健侧。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2016","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常心尖搏动位于？","options":["左侧第3肋间","左侧第5肋间锁骨中线内0.5-1.0cm","胸骨左缘第4肋间","右侧第5肋间"],"answer":1,"explanation":"正常心尖搏动位于第5肋间左锁骨中线内0.5-1.0cm，搏动范围2.0-2.5cm。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2017","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心尖区闻及舒张期隆隆样杂音提示？","options":["室间隔缺损","二尖瓣关闭不全","主动脉瓣狭窄","二尖瓣狭窄"],"answer":3,"explanation":"二尖瓣狭窄特征性杂音为心尖区舒张期隆隆样杂音，伴第一心音亢进。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2018","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心尖区闻及收缩期粗糙吹风样杂音提示？","options":["肺动脉瓣狭窄","二尖瓣狭窄","主动脉瓣关闭不全","二尖瓣关闭不全"],"answer":3,"explanation":"二尖瓣关闭不全为心尖区3/6级以上收缩期吹风样杂音，向左腋下传导。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2019","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"主动脉瓣第二听诊区闻及舒张期叹气样杂音提示？","options":["二尖瓣狭窄","主动脉瓣狭窄","主动脉瓣关闭不全","三尖瓣关闭不全"],"answer":2,"explanation":"主动脉瓣关闭不全在胸骨左缘第3肋间（第二听诊区）闻及舒张期叹气样杂音。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2020","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"主动脉瓣区闻及收缩期喷射样杂音提示？","options":["主动脉瓣狭窄","主动脉瓣关闭不全","二尖瓣关闭不全","房间隔缺损"],"answer":0,"explanation":"主动脉瓣狭窄在胸骨右缘第2肋间闻及收缩期喷射样杂音，向颈部传导。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2021","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第一心音增强见于？","options":["二尖瓣关闭不全","二尖瓣狭窄","主动脉瓣关闭不全","心肌梗死"],"answer":1,"explanation":"二尖瓣狭窄时左房压高、心室充盈时间延长，瓣膜位置低，第一心音亢进。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-2022","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第二心音逆分裂（反常分裂）提示？","options":["正常变异","完全性右束支传导阻滞","完全性左束支传导阻滞或主动脉瓣狭窄","二尖瓣狭窄"],"answer":2,"explanation":"第二心音逆分裂（吸气时分裂反而消失）见于左束支阻滞、主动脉瓣狭窄。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-2023","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"收缩期杂音3/6级以上提示？","options":["与心脏病无关","均为生理性","多为器质性心脏病","仅见于儿童"],"answer":2,"explanation":"3/6级以上收缩期杂音多为器质性；2/6级以下可为功能性。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2024","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹水患者移动性浊音阳性提示腹腔积液至少为？","options":["500 ml","100 ml","300 ml","1000 ml以上"],"answer":3,"explanation":"腹腔积液>1000ml可叩出移动性浊音；少量积液需超声检查。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2025","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹膜刺激征（压痛、反跳痛、肌紧张）提示？","options":["肠易激综合征","消化不良","慢性胃炎","急性腹膜炎"],"answer":3,"explanation":"腹膜刺激征为急性腹膜炎的重要体征，提示腹膜受炎症刺激。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2026","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"Murphy征（墨菲征）阳性提示？","options":["胃溃疡","急性胰腺炎","急性阑尾炎","急性胆囊炎"],"answer":3,"explanation":"墨菲征阳性（深压胆囊点时患者因疼痛屏气）提示急性胆囊炎。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2027","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性阑尾炎最重要的体征是？","options":["脐周压痛","全腹压痛","右上腹压痛","麦氏点（右下腹）固定压痛"],"answer":3,"explanation":"麦氏点（脐与右髂前上棘连线中外1/3交界处）固定压痛是阑尾炎最重要体征。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2028","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝掌和蜘蛛痣的形成机制是？","options":["凝血功能障碍","雄激素过多","肝功能减退致雌激素灭活减少","门脉高压直接作用"],"answer":2,"explanation":"肝脏对雌激素灭活减少，雌激素增多使小动脉扩张，形成蜘蛛痣、肝掌。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2029","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脾肿大伴腹水、腹壁静脉曲张提示？","options":["肝硬化门脉高压","急性肝炎","脾功能亢进（单纯）","肝癌晚期"],"answer":0,"explanation":"门脉高压三联征：脾大、侧支循环建立（腹壁静脉曲张、食管胃底静脉曲张）、腹水。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2030","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹部包块伴肠鸣音亢进、气过水声提示？","options":["腹膜炎","麻痹性肠梗阻","机械性肠梗阻","消化不良"],"answer":2,"explanation":"机械性肠梗阻肠鸣音亢进（气过水声、金属音）；麻痹性肠梗阻肠鸣音消失。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2031","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肠鸣音消失（持续听诊3-5分钟未闻及）提示？","options":["急性腹膜炎或麻痹性肠梗阻","机械性肠梗阻","饥饿","腹泻"],"answer":0,"explanation":"肠鸣音消失见于急性腹膜炎、麻痹性肠梗阻、低血钾等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2032","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"直肠指检对下列哪种疾病最有诊断价值？","options":["胃癌","直肠癌（低位）","肝癌","胰腺癌"],"answer":1,"explanation":"直肠指检可发现约70%的直肠癌（低位），是简便重要的检查。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2033","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"淋巴结触诊发现质地坚硬、固定、无压痛的包块提示？","options":["正常变异","淋巴结炎","结核性淋巴结炎","恶性肿瘤转移"],"answer":3,"explanation":"质硬、固定、无压痛、融合的淋巴结提示恶性肿瘤转移；质软、活动、压痛多为炎症。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2034","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺触诊发现震颤伴血管杂音提示？","options":["单纯性甲状腺肿","甲状腺功能亢进","甲状腺癌","亚急性甲状腺炎"],"answer":1,"explanation":"甲亢时甲状腺血流丰富，触诊震颤、听诊血管杂音（特征性体征）。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2035","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺肿大伴疼痛、发热提示？","options":["单纯性甲状腺肿","亚急性甲状腺炎","甲状腺功能亢进","甲状腺癌"],"answer":1,"explanation":"亚急性甲状腺炎甲状腺肿痛、触痛明显，常有上感前驱史。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2036","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"杵状指（趾）常见于？","options":["慢性缺氧性疾病（支扩、肺脓肿、发绀型先心病）","贫血","高血压","糖尿病"],"answer":0,"explanation":"杵状指见于慢性缺氧（支扩、肺脓肿、肺心病、发绀型先心病）和感染性心内膜炎等。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2037","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"反甲（匙状甲）提示？","options":["缺铁性贫血","慢性缺氧","甲亢","痛风"],"answer":0,"explanation":"匙状甲（反甲）是缺铁性贫血的特征表现之一。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2038","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"眼睑水肿伴蛋白尿提示？","options":["心源性水肿","肾性水肿","肝性水肿","营养不良性水肿"],"answer":1,"explanation":"肾性水肿晨起眼睑颜面肿，伴蛋白尿、血尿。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2039","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"黄疸伴胆囊肿大（Courvoisier征阳性）提示？","options":["胰头癌（无痛性进行性黄疸）","胆总管结石（绞痛）","急性胆囊炎","肝细胞性黄疸"],"answer":0,"explanation":"胰头癌压迫胆总管致无痛性进行性黄疸、胆囊肿大（库瓦济埃征）。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-2040","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"上腹部剧烈疼痛向腰背部放射提示？","options":["急性胰腺炎","急性胃炎","消化不良","肠易激综合征"],"answer":0,"explanation":"急性胰腺炎疼痛向腰背部呈带状放射，弯腰抱膝位可减轻。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2041","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"呕血伴剧烈腹痛、发热提示？","options":["胃癌（早期）","食管静脉曲张破裂","消化性溃疡（单纯）","胆道出血（胆绞痛+发热）"],"answer":3,"explanation":"胆道出血三联征：腹痛、黄疸、出血（呕血或黑便），常伴发热。","exam":"医疗编","__sub":"诊断学基础","diff":3,"id":"yl-2042","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"意识障碍伴烂苹果味呼吸提示？","options":["糖尿病酮症酸中毒","肝性脑病","尿毒症","酒精中毒"],"answer":0,"explanation":"酮症酸中毒呼气有烂苹果味（丙酮）；肝性脑病为肝臭味；尿毒症为氨味。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2043","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"意识障碍伴氨味（尿味）呼吸提示？","options":["肝性脑病","糖尿病酮症","尿毒症","肺性脑病"],"answer":2,"explanation":"尿毒症呼气有氨味（尿味），伴贫血、出血倾向等。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2044","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"意识障碍伴肝臭味提示？","options":["有机磷中毒","尿毒症","酮症酸中毒","肝性脑病"],"answer":3,"explanation":"肝性脑病呼气有肝臭味（硫醇类），伴扑翼样震颤。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2045","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"有机磷中毒的呼吸气味是？","options":["大蒜味","烂苹果味","氨味","肝臭味"],"answer":0,"explanation":"有机磷农药中毒呼气和呕吐物有大蒜味，伴瞳孔缩小、肌束震颤、分泌物增多。","exam":"医疗编","__sub":"诊断学基础","diff":1,"id":"yl-2046","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"意识障碍伴口唇樱桃红色提示？","options":["严重贫血","糖尿病酮症","亚硝酸盐中毒","一氧化碳中毒"],"answer":3,"explanation":"CO中毒皮肤黏膜呈樱桃红色（碳氧血红蛋白），有明确接触史。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2047","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"意识障碍伴口唇发绀（青紫色）提示？","options":["亚硝酸盐中毒（高铁血红蛋白血症）","一氧化碳中毒","酒精中毒","低血糖"],"answer":0,"explanation":"亚硝酸盐中毒高铁血红蛋白血症致口唇发绀，用亚甲蓝解救。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2048","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"低血糖昏迷的表现不包括？","options":["瞳孔散大、皮肤干燥","心悸、出汗、手抖","意识模糊","血糖<2.8mmol/L"],"answer":0,"explanation":"低血糖表现为交感兴奋（心悸、出汗、手抖）和神经缺糖症状；瞳孔散大、皮肤干燥是阿托品化或抗胆碱能表现。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2049","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"昏迷患者瞳孔散大、对光反射消失，最可能的诊断是？","options":["深昏迷或脑干功能衰竭","浅昏迷","嗜睡","癔症"],"answer":0,"explanation":"深昏迷时瞳孔散大、对光反射消失，提示脑干功能严重受损。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2050","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性阻塞性肺疾病（COPD）最重要的危险因素是？","options":["感染","空气污染","职业粉尘","吸烟"],"answer":3,"explanation":"吸烟是COPD最重要的发病因素，戒烟是延缓病情进展的最有效措施。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2051","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"COPD的诊断金标准是？","options":["肺功能检查（吸入支气管舒张剂后FEV₁/FVC<70%）","胸片","血气分析","胸部CT"],"answer":0,"explanation":"肺功能是COPD诊断的金标准：吸入舒张剂后FEV₁/FVC<70%提示持续气流受限。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2052","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"COPD急性加重最常见的诱因是？","options":["情绪激动","气候变化","呼吸道感染","饮食不当"],"answer":2,"explanation":"呼吸道感染（病毒或细菌）是COPD急性加重的最常见诱因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2053","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"支气管哮喘的本质是？","options":["支气管肿瘤","细菌感染","气道慢性炎症（多种细胞参与）","肺实质破坏"],"answer":2,"explanation":"哮喘为气道慢性炎症性疾病，由嗜酸性粒细胞、肥大细胞等多种细胞参与，气道高反应性为特征。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2054","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"支气管哮喘的典型表现是？","options":["咯血","持续性吸气性呼吸困难","咳嗽伴大量脓痰","发作性呼气性呼吸困难伴广泛哮鸣音"],"answer":3,"explanation":"哮喘典型表现为反复发作的喘息、呼气性呼吸困难，双肺广泛哮鸣音，可自行或用药后缓解。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2055","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"哮喘发作时首选的缓解药物是？","options":["抗生素","糖皮质激素口服","氨茶碱静滴","短效β₂受体激动剂（沙丁胺醇）"],"answer":3,"explanation":"沙丁胺醇等短效β₂激动剂迅速舒张支气管，是缓解急性发作的首选。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2056","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"哮喘长期控制的首选药物是？","options":["吸入性糖皮质激素","口服泼尼松","静脉甲泼尼龙","白三烯调节剂"],"answer":0,"explanation":"吸入性糖皮质激素是哮喘长期控制（抗炎）的首选药物。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2057","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"哮喘持续状态（重度发作）的处理不包括？","options":["雾化β₂激动剂","吸氧","立即使用吗啡镇静","静脉糖皮质激素"],"answer":2,"explanation":"吗啡抑制呼吸并释放组胺加重支气管痉挛，哮喘禁用。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2058","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"支气管扩张的典型临床表现是？","options":["刺激性干咳","慢性咳嗽、大量脓痰、反复咯血","胸痛伴呼吸困难","发热伴皮疹"],"answer":1,"explanation":"支扩三联征：慢性咳嗽、大量脓痰（静置分层）、反复咯血。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2059","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"支气管扩张确诊的首选检查是？","options":["高分辨率CT（HRCT）","胸片","支气管造影","肺功能"],"answer":0,"explanation":"HRCT显示支气管扩张的柱状或囊状改变，是确诊首选。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2060","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"社区获得性肺炎最常见的病原体是？","options":["铜绿假单胞菌","金黄色葡萄球菌","肺炎链球菌","厌氧菌"],"answer":2,"explanation":"社区获得性肺炎以肺炎链球菌最常见。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2061","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺炎链球菌肺炎的典型表现是？","options":["刺激性干咳","寒战高热、咳嗽、铁锈色痰","大量脓臭痰","咯血伴消瘦"],"answer":1,"explanation":"肺炎链球菌肺炎起病急骤、寒战高热、咳嗽、咳铁锈色痰，肺实变体征。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2062","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺炎链球菌肺炎的首选抗生素是？","options":["万古霉素","庆大霉素","四环素","青霉素G"],"answer":3,"explanation":"肺炎链球菌对青霉素敏感（耐青霉素株用头孢曲松或呼吸喹诺酮），首选青霉素G。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2063","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"金黄色葡萄球菌肺炎的特点是？","options":["铁锈色痰","易形成肺脓肿和脓胸","多见于健康青年","首选青霉素G"],"answer":1,"explanation":"金葡菌肺炎毒力强、易化脓，形成肺脓肿、脓胸，首选耐酶青霉素（苯唑西林）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2064","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺结核的主要传播途径是？","options":["消化道","呼吸道飞沫传播","血液","接触传播"],"answer":1,"explanation":"肺结核经呼吸道飞沫传播，开放性肺结核患者是主要传染源。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2065","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺结核确诊的最重要检查是？","options":["血沉","PPD试验","胸片","痰结核菌检查（涂片/培养）"],"answer":3,"explanation":"痰中找到结核分枝杆菌是确诊肺结核的最重要依据。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2066","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺结核化疗的原则是？","options":["单药长程","早期、联合、适量、规律、全程","症状消失即停药","大剂量冲击"],"answer":1,"explanation":"结核化疗十字原则：早期、联合、适量、规律、全程，防止复发和耐药。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2067","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺结核短程化疗的疗程一般为？","options":["2年","3个月","1年","6-9个月"],"answer":3,"explanation":"初治肺结核标准短程化疗6-9个月（2HRZE/4HR等方案）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2068","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"原发性肺结核的好发人群是？","options":["HIV患者","老年人","糖尿病患者","儿童"],"answer":3,"explanation":"原发性肺结核多见于儿童（初次感染），原发综合征为典型表现。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2069","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺癌的首选筛查方法是？","options":["胸片","低剂量螺旋CT","痰细胞学","肿瘤标志物"],"answer":1,"explanation":"低剂量螺旋CT是肺癌高危人群筛查的首选，能发现早期病变。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2070","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中央型肺癌最常见的组织类型是？","options":["腺癌","鳞癌（与吸烟关系密切）","小细胞癌","大细胞癌"],"answer":1,"explanation":"中央型肺癌以鳞癌和小细胞癌多见；周围型以腺癌多见。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2071","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小细胞肺癌的特点是？","options":["恶性度高、生长快、对放化疗敏感","生长慢","对放化疗不敏感","首选手术"],"answer":0,"explanation":"小细胞肺癌恶性度高、早期转移，以放化疗为主（手术作用有限）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2072","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸腔积液中，渗出液的特点是？","options":["蛋白<25g/L","外观清亮透明","蛋白含量高、比重>1.018、细胞数多","比重<1.015"],"answer":2,"explanation":"渗出液蛋白>30g/L、比重>1.018、细胞数多，见于炎症、肿瘤；漏出液相反。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2073","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"结核性胸膜炎胸腔积液的特点是？","options":["糖正常（一般）","以中性粒细胞为主","以淋巴细胞为主、ADA升高、蛋白高","pH明显升高"],"answer":2,"explanation":"结核性胸水为渗出液，淋巴细胞为主、ADA（腺苷脱氨酶）>45U/L有诊断价值。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2074","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"癌性胸腔积液的特点是？","options":["以中性粒细胞为主","ADA明显升高","血性积液、CEA升高、可找到癌细胞","糖升高"],"answer":2,"explanation":"癌性胸水常为血性，CEA升高，脱落细胞学找到癌细胞可确诊。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2075","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性心力衰竭最常见的病因是？","options":["先天性心脏病","心肌病","心脏瓣膜病","冠心病和高血压"],"answer":3,"explanation":"冠心病和高血压是我国慢性心衰最主要的病因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2076","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"左心衰竭的主要表现是？","options":["肝大","下肢水肿","颈静脉怒张","呼吸困难（劳力性→夜间阵发性→端坐呼吸）"],"answer":3,"explanation":"左心衰竭以肺淤血为主，表现为呼吸困难（进行性加重）和咳嗽咳痰。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2077","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"右心衰竭的主要表现是？","options":["夜间阵发性呼吸困难","体循环淤血（颈静脉怒张、肝大、下肢水肿）","粉红色泡沫痰","端坐呼吸"],"answer":1,"explanation":"右心衰竭以体循环淤血为主：颈静脉怒张、肝大压痛、下肢凹陷性水肿。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2078","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性左心衰竭的典型表现是？","options":["突发严重呼吸困难、咳粉红色泡沫痰","下肢水肿","颈静脉怒张","肝区疼痛"],"answer":0,"explanation":"急性左心衰（肺水肿）：突发呼吸困难、端坐呼吸、粉红色泡沫痰、满肺湿啰音。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2079","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性左心衰竭的首选处理是？","options":["立即抗生素","立即洋地黄","高流量吸氧、坐位、利尿、扩血管","立即补液"],"answer":2,"explanation":"急性肺水肿：端坐位、高流量吸氧（可加酒精消泡）、快速利尿（呋塞米）、扩血管（硝酸甘油）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2080","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"洋地黄中毒最常见的心律失常是？","options":["室性早搏（二联律）","房室传导阻滞","窦性心动过缓","房颤"],"answer":0,"explanation":"洋地黄中毒最常见室性早搏（尤其二联律），特征性表现为快速心律失常伴传导阻滞。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2081","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"洋地黄中毒的处理是？","options":["加大剂量","立即停药、补钾、必要时用苯妥英钠","立即电复律","继续观察"],"answer":1,"explanation":"洋地黄中毒立即停药、纠正低钾，室性心律失常用苯妥英钠或利多卡因。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2082","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心衰患者使用β受体阻滞剂的原则是？","options":["小剂量开始、逐渐加量、长期维持","大剂量冲击","急性期立即大剂量","症状加重时加量"],"answer":0,"explanation":"β受体阻滞剂改善心衰预后，须小剂量起始、缓慢加量、长期维持，急性失代偿期慎用。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2083","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"心衰患者利尿剂的主要作用是？","options":["抗心律失常","增强心肌收缩力","减慢心率","减轻水钠潴留、降低心脏前负荷"],"answer":3,"explanation":"利尿剂排钠排水，减轻前负荷和淤血症状，是心衰基础治疗。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2084","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压的诊断标准是？","options":["舒张压≥85mmHg","一次测量≥140/90mmHg","收缩压≥130mmHg","非同日3次测量收缩压≥140mmHg和/或舒张压≥90mmHg"],"answer":3,"explanation":"高血压诊断标准：非同日3次测量≥140/90mmHg。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2085","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压最常见的心脏并发症是？","options":["心包积液","左心室肥厚和心力衰竭","感染性心内膜炎","心房黏液瘤"],"answer":1,"explanation":"长期高血压致左心室肥厚、扩大，最终心力衰竭。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2086","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压最严重的并发症是？","options":["眼底出血","脑卒中（脑出血、脑梗死）","肾功能不全","主动脉夹层"],"answer":1,"explanation":"脑卒中是高血压最严重的并发症，是我国高血压患者主要死因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2087","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压急症的处理原则是？","options":["立即口服降压药","静脉降压药物迅速降压（1小时内平均压降低不超过25%）","快速降至正常低值","观察等待"],"answer":1,"explanation":"高血压急症静脉用药，初期1小时内平均动脉压下降不超过25%，防止重要器官灌注不足。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2088","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压患者降压治疗的目标值（一般患者）是？","options":["<140/90 mmHg","<160/100 mmHg","<120/70 mmHg（所有患者）","<150/100 mmHg"],"answer":0,"explanation":"一般高血压患者血压控制目标<140/90mmHg，耐受良好或高危者可<130/80mmHg。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2089","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压伴痛风患者不宜使用？","options":["卡托普利","氨氯地平","氢氯噻嗪","美托洛尔"],"answer":2,"explanation":"噻嗪类利尿药升高血尿酸，痛风患者慎用或禁用。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2090","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高血压伴双侧肾动脉狭窄患者禁用？","options":["钙拮抗剂","ACEI/ARB","β受体阻滞剂","利尿剂"],"answer":1,"explanation":"双侧肾动脉狭窄者用ACEI/ARB可致急性肾衰竭，禁用。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2091","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"冠心病的最重要危险因素是？","options":["血脂异常（LDL-C升高）","年龄","性别","家族史"],"answer":0,"explanation":"LDL-C升高是动脉粥样硬化最重要的危险因素，是降脂治疗主要目标。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2092","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"冠心病的确诊检查是？","options":["心电图","冠状动脉造影","运动平板试验","心脏彩超"],"answer":1,"explanation":"冠脉造影是冠心病诊断的金标准，可明确狭窄部位和程度。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2093","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"稳定型心绞痛发作时的处理是？","options":["立即休息、舌下含服硝酸甘油","口服阿司匹林","静脉输液","立即溶栓"],"answer":0,"explanation":"心绞痛发作立即停止活动、舌下含服硝酸甘油，1-2分钟缓解。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2094","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"变异型心绞痛的首选药物是？","options":["β受体阻滞剂","钙通道阻滞剂（地尔硫䓬）","利尿剂","ACEI"],"answer":1,"explanation":"变异型心绞痛由冠脉痉挛引起，钙通道阻滞剂为首选；β受体阻滞剂可加重痉挛。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2095","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性心肌梗死的典型表现是？","options":["胸痛持续数秒","阵发性胸闷","胸骨后剧烈持久的压榨性疼痛，硝酸甘油不能缓解","与呼吸有关的刺痛"],"answer":2,"explanation":"心梗疼痛剧烈持久（>30分钟），休息和含服硝酸甘油不缓解，伴大汗、濒死感。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2096","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性心肌梗死诊断最有价值的血液学指标是？","options":["肌钙蛋白（cTnI/cTnT）","肌酸激酶（CK）","血常规","血沉"],"answer":0,"explanation":"肌钙蛋白特异性、敏感性最高，是心梗诊断的首选心肌标志物。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2097","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性心肌梗死发病后肌钙蛋白升高的时间是？","options":["1周后升高","立即升高","24小时后升高","3-4小时开始升高，持续7-10天"],"answer":3,"explanation":"肌钙蛋白发病3-4小时升高，11-24小时达高峰，持续7-10天。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2098","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性ST段抬高型心肌梗死的首选再灌注治疗是？","options":["静脉溶栓（无条件行PCI时）","口服阿司匹林观察","发病12小时内急诊PCI（或溶栓）","冠脉搭桥"],"answer":2,"explanation":"STEMI首选发病12小时内急诊PCI；无条件时发病12小时内（最好3小时内）静脉溶栓。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2099","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性心肌梗死患者绝对卧床的时间一般为？","options":["1个月","1周","24小时即可下床","发病后12小时内绝对卧床"],"answer":3,"explanation":"急性心梗12小时内绝对卧床、心电监护，之后根据病情逐步活动。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2100","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性心肌梗死最常见的死亡原因是？","options":["心室颤动（心律失常）","心源性休克","心力衰竭","心脏破裂"],"answer":0,"explanation":"急性心梗早期（24小时内）死亡原因以室颤为主，需心电监护、除颤备用。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2101","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"风湿性心脏病最常受累的瓣膜是？","options":["肺动脉瓣","主动脉瓣","三尖瓣","二尖瓣"],"answer":3,"explanation":"风心病以二尖瓣最常受累（狭窄最典型），其次为主动脉瓣。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2102","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"二尖瓣狭窄的典型体征是？","options":["心尖区收缩期杂音","心尖区舒张期隆隆样杂音","主动脉瓣区舒张期杂音","水冲脉"],"answer":1,"explanation":"二尖瓣狭窄：心尖区舒张期隆隆样杂音、第一心音亢进、开瓣音。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2103","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"二尖瓣狭窄最常见的并发症是？","options":["感染性心内膜炎","心房颤动","栓塞","肺部感染"],"answer":1,"explanation":"房颤是二尖瓣狭窄最常见并发症，发生后血栓栓塞风险增加。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2104","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"感染性心内膜炎最常见的病原体是？","options":["结核杆菌","金黄色葡萄球菌（静脉药瘾者）","大肠埃希菌","草绿色链球菌（自体瓣膜）"],"answer":3,"explanation":"自体瓣膜感染性心内膜炎以草绿色链球菌最常见；静脉药瘾者以金葡菌常见。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2105","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"感染性心内膜炎确诊依据是？","options":["血培养阳性（多次）","发热","心脏杂音","血沉增快"],"answer":0,"explanation":"血培养阳性是感染性心内膜炎最重要的确诊依据，需多次采血培养。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2106","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病毒性心肌炎最常见的病原体是？","options":["乙肝病毒","流感病毒","柯萨奇B组病毒","EB病毒"],"answer":2,"explanation":"病毒性心肌炎以柯萨奇B组病毒最常见，发病前1-3周常有病毒感染前驱症状。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2107","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"病毒性心肌炎的治疗不包括？","options":["营养心肌","休息（最重要）","早期大剂量糖皮质激素常规使用","对症处理"],"answer":2,"explanation":"病毒性心肌炎以休息、营养心肌、对症为主，糖皮质激素不常规使用（重症或自身免疫参与时考虑）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2108","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性胃炎确诊的检查是？","options":["胃镜及活检","钡餐","幽门螺杆菌呼气试验","腹部超声"],"answer":0,"explanation":"胃镜+黏膜活检是慢性胃炎确诊手段，可同时检测幽门螺杆菌。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2109","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"消化性溃疡的主要病因是？","options":["饮食不规律","幽门螺杆菌感染和胃酸分泌过多","精神因素","遗传"],"answer":1,"explanation":"消化性溃疡发病是胃酸、胃蛋白酶的侵袭与黏膜防御失衡，Hp感染和胃酸是主要因素。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2110","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"消化性溃疡最典型的表现是？","options":["恶心呕吐","慢性、周期性、节律性上腹痛","反酸嗳气","腹泻"],"answer":1,"explanation":"消化性溃疡特点：慢性病程、周期性发作、节律性疼痛（胃溃疡餐后痛，十二指肠溃疡空腹痛/夜间痛）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2111","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"十二指肠溃疡疼痛的特点是？","options":["餐后立即痛","空腹痛（餐后3-4小时）和夜间痛，进食后缓解","无规律","排便后缓解"],"answer":1,"explanation":"十二指肠溃疡疼痛-进食-缓解的节律；胃溃疡为进食-疼痛-缓解。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2112","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"消化性溃疡最常见的并发症是？","options":["出血","穿孔","幽门梗阻","癌变"],"answer":0,"explanation":"出血是消化性溃疡最常见并发症（十二指肠溃疡多见），表现为呕血或黑便。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2113","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"消化性溃疡穿孔的表现是？","options":["黑便","呕血","突发剧烈腹痛、腹膜刺激征、膈下游离气体","黄疸"],"answer":2,"explanation":"溃疡穿孔：突发刀割样腹痛、板状腹、膈下游离气体，需急诊手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2114","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胃溃疡癌变的警惕信号不包括？","options":["规律性疼痛加重","疼痛规律改变（失去节律）","消瘦、贫血","大便隐血持续阳性"],"answer":0,"explanation":"胃溃疡疼痛规律改变、消瘦、贫血、隐血持续阳性提示癌变；规律性疼痛加重表述不清，规律改变才是警示。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2115","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝硬化最常见的病因是？","options":["胆汁淤积","酒精性肝病","药物性肝损害","乙型病毒性肝炎"],"answer":3,"explanation":"我国肝硬化以乙肝后肝硬化最常见；欧美以酒精性为主。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2116","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝硬化门脉高压的表现不包括？","options":["腹水","脾大","黄疸进行性加深（必然）","侧支循环建立"],"answer":2,"explanation":"门脉高压表现：脾大、侧支循环、腹水；黄疸为肝功能减退表现，非门脉高压必然表现。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2117","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝硬化最严重的并发症是？","options":["上消化道出血","肝性脑病","感染","肝肾综合征"],"answer":1,"explanation":"肝性脑病是肝硬化最严重的并发症，也是主要死因之一。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2118","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝硬化食管胃底静脉曲张破裂出血的首选急救措施是？","options":["立即手术","口服止血药","内镜下止血（套扎/硬化）+药物（生长抑素）","输血观察"],"answer":2,"explanation":"食管胃底静脉曲张破裂出血：生长抑素（奥曲肽）+内镜下套扎/硬化剂治疗，必要时三腔二囊管。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2119","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝性脑病的常见诱因不包括？","options":["便秘","低蛋白饮食","感染","高蛋白饮食、感染、便秘、消化道出血"],"answer":3,"explanation":"高蛋白饮食（产氨增多）、感染、便秘、出血是肝性脑病常见诱因；低蛋白饮食是预防措施。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2120","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝性脑病最具特征性的体征是？","options":["黄疸","下肢水肿","腹水","扑翼样震颤"],"answer":3,"explanation":"扑翼样震颤是肝性脑病（前驱期、昏迷前期）的特征性体征。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2121","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肝性脑病饮食的原则是？","options":["高脂饮食","高蛋白饮食","禁食碳水化合物","限制蛋白质摄入（以植物蛋白为主）"],"answer":3,"explanation":"肝性脑病限制蛋白摄入、以植物蛋白为主，减少氨的来源。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2122","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"原发性肝癌最常见的病因是？","options":["血吸虫病","酒精","黄曲霉毒素（协同因素）","乙型肝炎病毒感染"],"answer":3,"explanation":"乙肝病毒感染是我国原发性肝癌最主要的病因（肝炎-肝硬化-肝癌三部曲）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2123","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"原发性肝癌的首选筛查方法是？","options":["CT","甲胎蛋白（AFP）+肝脏超声","MRI","肝穿刺活检"],"answer":1,"explanation":"AFP+超声是肝癌高危人群（乙肝、肝硬化）的首选筛查组合。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2124","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"原发性肝癌的确诊方法是？","options":["AFP升高","肝穿刺活检（病理）","超声","CT增强"],"answer":1,"explanation":"病理学检查（肝穿刺活检）是肝癌确诊的金标准；AFP>400μg/L结合影像可临床诊断。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2125","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性胰腺炎最常见的病因是？","options":["高脂血症","大量饮酒","暴饮暴食","胆道疾病（胆石症）"],"answer":3,"explanation":"胆石症是我国急性胰腺炎最常见的病因（胆源性胰腺炎）；饮酒是重要诱因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2126","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性胰腺炎的主要表现是？","options":["腹泻","阵发性绞痛","转移性右下腹痛","持续性上腹痛向腰背部放射，弯腰抱膝可减轻"],"answer":3,"explanation":"急性胰腺炎：持续性上腹痛向腰背放射，恶心呕吐后腹痛不缓解（与胃病区别）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2127","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性胰腺炎治疗的基本原则是？","options":["大量进食","立即手术","禁食胃肠减压、抑制胰酶分泌、补液","抗生素为主"],"answer":2,"explanation":"急性胰腺炎以内科治疗为主：禁食胃肠减压、抑酸抑酶、液体复苏；胆源性或重症者手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2128","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"溃疡性结肠炎的典型表现是？","options":["脂肪泻","水样便无脓血","便秘","黏液脓血便伴腹痛、里急后重"],"answer":3,"explanation":"溃疡性结肠炎：腹泻（黏液脓血便）、腹痛（左下腹）、里急后重，反复发作。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2129","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"溃疡性结肠炎病变主要累及？","options":["直肠和乙状结肠（连续性病变）","回肠末端","全小肠","胃"],"answer":0,"explanation":"溃疡性结肠炎病变从直肠开始连续向上蔓延，黏膜弥漫性炎症。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2130","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"克罗恩病的病变特点是？","options":["仅累及直肠","连续性病变","全消化道节段性（跳跃性）病变，好发回肠末端","仅累及结肠"],"answer":2,"explanation":"克罗恩病：节段性（跳跃性）全消化道病变，好发回肠末端和回盲部，可形成瘘管。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2131","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性肾小球肾炎的主要表现是？","options":["大量白细胞尿","蛋白尿、血尿、高血压、水肿","尿频尿急尿痛","肾绞痛"],"answer":1,"explanation":"慢性肾炎基本表现：蛋白尿、血尿、高血压、水肿，缓慢进展为肾衰。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2132","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾病综合征的诊断标准是？","options":["大量蛋白尿（>3.5g/24h）+低白蛋白血症（<30g/L）","血尿+蛋白尿","高血压+水肿","氮质血症+贫血"],"answer":0,"explanation":"肾病综合征两要素：大量蛋白尿（>3.5g/24h）和低白蛋白血症（<30g/L），水肿和高脂血症为继发。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2133","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾病综合征最常见的并发症是？","options":["蛋白质营养不良","血栓","急性肾损伤","感染"],"answer":3,"explanation":"感染是肾病综合征最常见并发症（大量免疫球蛋白丢失），血栓栓塞为其严重并发症。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2134","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肾小球肾炎（链球菌感染后）的前驱期一般为？","options":["感染后1个月以上","感染后1-2天","感染后1-3周","感染同时"],"answer":2,"explanation":"链球菌感染后1-3周出现血尿、蛋白尿、水肿、高血压（急性肾炎综合征）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2135","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肾盂肾炎的典型表现是？","options":["下肢水肿","无痛性血尿","大量蛋白尿","发热、腰痛、膀胱刺激征"],"answer":3,"explanation":"急性肾盂肾炎：发热寒战、腰痛（肾区叩痛）、尿频尿急尿痛。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2136","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性肾衰竭最常见的病因是？","options":["慢性肾小球肾炎","糖尿病肾病","高血压肾病","多囊肾"],"answer":0,"explanation":"我国慢性肾衰以慢性肾小球肾炎为最常见病因（糖尿病肾病上升趋势）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2137","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性肾衰竭患者饮食的原则是？","options":["高磷饮食","高蛋白饮食","低磷高钾饮食","优质低蛋白饮食"],"answer":3,"explanation":"慢性肾衰优质低蛋白饮食，减少氮质潴留；限磷，避免高钾食物。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2138","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"尿毒症最早出现的症状是？","options":["抽搐","皮肤瘙痒","心力衰竭","消化系统症状（食欲不振、恶心）"],"answer":3,"explanation":"尿毒症毒素刺激胃肠道，食欲不振、恶心是最早、最常见的症状。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2139","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"尿毒症贫血的主要原因是？","options":["促红细胞生成素减少","铁摄入不足（唯一）","溶血","失血"],"answer":0,"explanation":"肾脏产生促红细胞生成素减少是尿毒症贫血的主要原因，用EPO治疗。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2140","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"缺铁性贫血最常见的病因是？","options":["铁吸收障碍","铁摄入不足（成人）","慢性失血（女性月经过多、消化道慢性失血）","溶血"],"answer":2,"explanation":"成人缺铁性贫血以慢性失血最常见；婴幼儿以铁摄入不足为主。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2141","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"缺铁性贫血的典型血象是？","options":["大细胞性贫血","小细胞低色素性贫血","正细胞性贫血","白细胞减少"],"answer":1,"explanation":"缺铁性贫血：红细胞小、中心淡染区扩大（小细胞低色素），MCV、MCH、MCHC均降低。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2142","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"缺铁性贫血确诊的检查是？","options":["血常规","血清铁降低（单项）","血清铁蛋白降低","骨髓穿刺"],"answer":2,"explanation":"血清铁蛋白是反映储存铁最敏感指标，降低可确诊缺铁。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2143","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"口服铁剂治疗缺铁性贫血，网织红细胞开始升高的时间是？","options":["服药后3-4天","服药后1小时","服药后1周","服药后1个月"],"answer":0,"explanation":"铁剂治疗后3-4天网织红细胞开始升高，7-10天达高峰。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2144","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"巨幼细胞贫血的病因是？","options":["再生障碍","缺铁","溶血","叶酸和（或）维生素B12缺乏"],"answer":3,"explanation":"叶酸或B12缺乏致DNA合成障碍，红细胞大（大细胞性），骨髓巨幼变。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2145","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"再生障碍性贫血的主要表现是？","options":["贫血、出血、感染（全血细胞减少）","单纯贫血","脾大","黄疸"],"answer":0,"explanation":"再障三系减少：贫血、出血（血小板少）、感染（白细胞少），肝脾一般不大。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2146","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"再生障碍性贫血确诊的检查是？","options":["铁蛋白","血常规","网织红细胞","骨髓穿刺（增生低下）"],"answer":3,"explanation":"再障骨髓象：多部位增生减低或重度减低，非造血细胞增多。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2147","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性白血病的主要表现是？","options":["贫血、出血、感染、浸润（肝脾淋巴结肿大）","单纯乏力","黄疸","腹水"],"answer":0,"explanation":"急性白血病四联：贫血、出血、感染、白血病细胞浸润（骨痛、肝脾淋巴结肿大）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2148","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性白血病确诊的依据是？","options":["骨髓象（原始细胞≥20%）","血常规","淋巴结活检","免疫学检查"],"answer":0,"explanation":"骨髓原始细胞≥20%是急性白血病的确诊标准（WHO标准）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2149","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性白血病化疗后最严重的并发症是？","options":["恶心呕吐","脱发","骨髓抑制（感染、出血）","口腔溃疡"],"answer":2,"explanation":"化疗后骨髓抑制期（7-14天）感染和出血风险最高，需保护隔离。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2150","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"特发性血小板减少性紫癜（ITP）的主要表现是？","options":["脾大明显","关节肿痛","皮肤黏膜出血（瘀点、紫癜）","溶血"],"answer":2,"explanation":"ITP以皮肤黏膜出血为主，血小板减少、骨髓巨核细胞成熟障碍。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2151","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺功能亢进症最常见的原因是？","options":["结节性甲状腺肿","弥漫性毒性甲状腺肿（Graves病）","甲状腺癌","亚急性甲状腺炎"],"answer":1,"explanation":"Graves病是甲亢最常见病因，表现为高代谢症候群、甲状腺肿大、眼征。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2152","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲亢的典型表现不包括？","options":["甲状腺肿大","心悸、多汗、消瘦","体重增加","眼征（突眼）"],"answer":2,"explanation":"甲亢代谢亢进：心悸、多汗、食欲亢进但消瘦、手抖、突眼；体重增加不是甲亢表现。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2153","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲亢诊断最敏感的指标是？","options":["T4","T3","血清TSH（促甲状腺激素）","甲状腺摄碘率"],"answer":2,"explanation":"TSH是最敏感的筛查指标（甲亢时降低）；FT3、FT4升高确诊。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2154","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲亢治疗的首选方法（成人初治）是？","options":["抗甲状腺药物（甲巯咪唑）","立即手术","碘131治疗","甲状腺素替代"],"answer":0,"explanation":"成人初治甲亢首选抗甲状腺药物（甲巯咪唑、丙硫氧嘧啶），疗程1.5-2年。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2155","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲亢危象的诱因不包括？","options":["精神刺激","感染、手术、创伤","放射性碘治疗后","受凉感冒（轻度）"],"answer":3,"explanation":"甲亢危象诱因：感染、手术、创伤、精神刺激、碘治疗早期等应激状态；轻度受凉一般不诱发。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2156","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲亢危象的表现是？","options":["嗜睡、体重增加","低热、心率慢","高热、大汗、心动过速（>140次/分）、烦躁、呕吐腹泻","血压升高、便秘"],"answer":2,"explanation":"甲亢危象：高热大汗、心率显著增快、烦躁谵妄、呕吐腹泻，死亡率高，需紧急处理。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2157","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺功能减退症的主要表现是？","options":["消瘦","心悸、多汗","代谢减慢（怕冷、乏力、水肿、体重增加）","突眼"],"answer":2,"explanation":"甲减：怕冷、乏力、嗜睡、黏液性水肿、体重增加、心率慢、便秘。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2158","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲减最严重的并发症是？","options":["心包积液","黏液性水肿昏迷","贫血","高脂血症"],"answer":1,"explanation":"黏液性水肿昏迷是甲减最严重的并发症，表现为低体温、心动过缓、意识障碍。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2159","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病最常见的类型是？","options":["1型糖尿病","2型糖尿病","妊娠糖尿病","特殊类型糖尿病"],"answer":1,"explanation":"2型糖尿病占90%以上，多见于成人，与胰岛素抵抗和分泌不足有关。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2160","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病的典型症状是？","options":["多饮、多食、多尿、体重减轻（三多一少）","多汗、心悸","水肿、少尿","便秘、腹胀"],"answer":0,"explanation":"糖尿病典型三多一少：多尿、多饮、多食、体重减轻。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2161","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病最基本的治疗措施是？","options":["饮食治疗和运动","口服降糖药","胰岛素","血糖监测"],"answer":0,"explanation":"饮食治疗是糖尿病一切治疗的基础，终身坚持。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2162","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"1型糖尿病的治疗必须使用？","options":["胰岛素","口服降糖药","饮食控制即可","运动疗法"],"answer":0,"explanation":"1型糖尿病胰岛β细胞破坏、胰岛素绝对缺乏，必须胰岛素治疗。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2163","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病最常见的急性并发症是？","options":["高渗性昏迷","低血糖昏迷","糖尿病酮症酸中毒","乳酸性酸中毒"],"answer":2,"explanation":"酮症酸中毒（DKA）是糖尿病最常见的急性并发症，诱因为感染、胰岛素中断等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2164","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病酮症酸中毒的特征表现是？","options":["便秘","低热","呼吸深大（Kussmaul呼吸）、烂苹果味、脱水","黄疸"],"answer":2,"explanation":"DKA：脱水、深大呼吸、烂苹果味、恶心呕吐、意识障碍，血糖高、酮体阳性。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2165","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病酮症酸中毒治疗的关键是？","options":["补液（首要）+小剂量胰岛素","立即补钾","立即纠酸","立即降糖至正常"],"answer":0,"explanation":"DKA治疗首要措施是补液（恢复血容量），同时小剂量胰岛素持续静滴。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2166","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病微血管病变最特征性的表现是？","options":["糖尿病肾病和糖尿病视网膜病变","冠心病","脑梗死","下肢动脉硬化"],"answer":0,"explanation":"微血管病变特征：糖尿病肾病、视网膜病变、神经病变；大血管病变为冠心病、脑卒中等。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2167","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病肾病最早期的表现是？","options":["大量蛋白尿","微量白蛋白尿","血肌酐升高","水肿"],"answer":1,"explanation":"糖尿病肾病早期表现为微量白蛋白尿，定期筛查尿微量白蛋白/肌酐比值。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2168","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"糖尿病足的主要预防措施是？","options":["控制血糖+足部护理（避免破损感染）","截肢","热敷","穿紧鞋"],"answer":0,"explanation":"糖尿病足预防：控制血糖、每日检查足部、避免破损、穿宽松鞋袜、及时处理胼胝。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2169","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"低血糖的诊断标准（糖尿病患者接受降糖治疗时）是？","options":["血糖≤3.9 mmol/L","血糖≤2.8 mmol/L","血糖≤5.0 mmol/L","血糖≤6.1 mmol/L"],"answer":0,"explanation":"接受药物治疗糖尿病患者血糖≤3.9mmol/L即为低血糖，需立即处理。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2170","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"低血糖昏迷的紧急处理是？","options":["立即静脉注射50%葡萄糖","立即注射胰岛素","口服降糖药","大量饮水"],"answer":0,"explanation":"低血糖昏迷立即静注50%葡萄糖40-60ml，清醒后继续进食。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2171","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"类风湿关节炎的基本病理改变是？","options":["骨质增生","血管炎","滑膜炎","软骨退变"],"answer":2,"explanation":"类风湿关节炎基本病理为滑膜炎，滑膜增生形成血管翳，侵蚀软骨骨质。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2172","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"类风湿关节炎的典型关节表现是？","options":["游走性大关节痛","单侧大关节肿痛","对称性小关节（近端指间、掌指、腕）晨僵","无痛性关节畸形"],"answer":2,"explanation":"RA：对称性多关节炎（腕、掌指、近端指间），晨僵>1小时，晚期关节畸形。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2173","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"类风湿关节炎的诊断性抗体是？","options":["类风湿因子（RF）和抗CCP抗体","抗核抗体","抗dsDNA抗体","抗-HBs"],"answer":0,"explanation":"RF和抗CCP抗体是RA的诊断性抗体，抗CCP特异性更高。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2174","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"系统性红斑狼疮最常累及的器官是？","options":["肺","心脏","肾脏（狼疮性肾炎）","神经系统"],"answer":2,"explanation":"SLE最常累及肾脏（狼疮性肾炎），是主要死因之一。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2175","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"系统性红斑狼疮的特征性表现是？","options":["关节痛","面部蝶形红斑","脱发","口腔溃疡"],"answer":1,"explanation":"面部蝶形红斑是SLE的特征性皮疹，具有诊断意义。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2176","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"系统性红斑狼疮治疗的基础药物是？","options":["羟氯喹（联合糖皮质激素）","抗生素","免疫球蛋白","环磷酰胺（重症）"],"answer":0,"explanation":"羟氯喹是SLE的基础用药，可减少复发和激素用量；重症用环磷酰胺冲击。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2177","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"有机磷农药中毒的主要机制是？","options":["麻痹呼吸中枢","抑制细胞色素氧化酶","阻断神经肌肉接头","抑制胆碱酯酶，乙酰胆碱蓄积"],"answer":3,"explanation":"有机磷抑制胆碱酯酶，乙酰胆碱蓄积产生毒蕈碱样（M）和烟碱样（N）症状。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2178","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"有机磷中毒毒蕈碱样症状的表现是？","options":["瞳孔散大","肌束震颤","瞳孔缩小、流涎、多汗、支气管分泌物增多","皮肤干燥"],"answer":2,"explanation":"M样症状：瞳孔缩小、腺体分泌增多（流涎、多汗、肺水肿）、平滑肌痉挛。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2179","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"有机磷中毒烟碱样症状的表现是？","options":["支气管痉挛","瞳孔缩小","流涎","肌束震颤、肌肉痉挛"],"answer":3,"explanation":"N样症状：肌束震颤、肌肉痉挛、无力；M样症状为腺体分泌和平滑肌痉挛。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2180","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"有机磷中毒的特效解毒药是？","options":["阿托品+氯解磷定","纳洛酮","美蓝","亚硝酸钠"],"answer":0,"explanation":"阿托品对抗M样症状，氯解磷定恢复胆碱酯酶活性（对抗N样症状），两药合用。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2181","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"阿托品化的表现不包括？","options":["瞳孔较前扩大","瞳孔缩小","口干、皮肤干燥","肺部啰音减少"],"answer":1,"explanation":"阿托品化：瞳孔扩大、口干、皮肤干燥、心率增快、肺部啰音减少；瞳孔缩小提示未达阿托品化或中毒加深。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2182","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"一氧化碳中毒最敏感的组织是？","options":["肾脏","肝脏","脑和心脏","皮肤"],"answer":2,"explanation":"脑和心肌对缺氧最敏感，CO中毒以神经系统损害为主。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2183","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"一氧化碳中毒迟发性脑病的发生时间是？","options":["中毒后立即","中毒当时","清醒后1年","清醒后2-60天"],"answer":3,"explanation":"部分CO中毒患者清醒后2-60天出现痴呆、精神症状、帕金森表现等迟发性脑病。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2184","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中暑高热（热射病）的首要处理是？","options":["应用退热药","补液","吸氧","迅速降温（物理降温为主）"],"answer":3,"explanation":"热射病死亡率高，首要措施是迅速降温（体外+体内降温），同时补液、护器官。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2185","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"淹溺患者救出后首要处理是？","options":["注射呼吸兴奋剂","控水","保暖","清理呼吸道、心肺复苏"],"answer":3,"explanation":"淹溺急救：立即清理口鼻异物、心肺复苏（CPR），不主张长时间控水耽误复苏。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2186","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"电击伤现场急救的首要措施是？","options":["心肺复苏","迅速脱离电源","包扎伤口","注射破伤风抗毒素"],"answer":1,"explanation":"电击伤急救：先断电（用绝缘物挑开电线），再评估呼吸心跳并行CPR。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2187","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"细菌性食物中毒的特点是？","options":["集体发病、潜伏期短、以胃肠道症状为主","散发、潜伏期长","以神经系统症状为主","不发热"],"answer":0,"explanation":"细菌性食物中毒：进食同一食物后短期内集体发病，恶心呕吐腹泻为主。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2188","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"沙门菌食物中毒的潜伏期一般为？","options":["1周","1小时","3天","4-24小时（多在12-24小时）"],"answer":3,"explanation":"沙门菌食物中毒潜伏期4-24小时，表现为发热、恶心呕吐、腹泻。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2189","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"河豚毒素中毒的主要表现是？","options":["皮疹","剧烈呕吐","腹泻","口唇麻木、四肢无力（神经麻痹）"],"answer":3,"explanation":"河豚毒素阻断钠通道，口唇舌尖麻木、四肢无力、呼吸麻痹，无特效解毒药。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2190","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"亚硝酸盐中毒的机制是？","options":["抑制胆碱酯酶","使血红蛋白氧化为高铁血红蛋白，失去携氧能力","麻痹呼吸中枢","破坏红细胞膜"],"answer":1,"explanation":"亚硝酸盐氧化血红蛋白为高铁血红蛋白，皮肤黏膜发绀，用亚甲蓝解救。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2191","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性上呼吸道感染最常见的病原体是？","options":["真菌","细菌","支原体","病毒"],"answer":3,"explanation":"普通感冒90%以上由病毒引起（鼻病毒、冠状病毒等），不需常规抗生素。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2192","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性扁桃体炎最常见的病原体是？","options":["溶血性链球菌","病毒","支原体","真菌"],"answer":0,"explanation":"急性扁桃体炎以溶血性链球菌常见，需足量青霉素类抗生素治疗。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2193","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性支气管炎的诊断标准是？","options":["咳嗽1个月","咳嗽咳痰每年3个月、连续2年以上","咳嗽2年、每年1个月","咳血1年"],"answer":1,"explanation":"慢支诊断：咳嗽咳痰每年持续3个月、连续2年或以上，并排除其他心肺疾病。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2194","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"慢性支气管炎急性发作的首要治疗是？","options":["镇咳","控制感染","祛痰","平喘"],"answer":1,"explanation":"慢支急性发作多由感染诱发，控制感染是首要治疗。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2195","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺心病的最主要病因是？","options":["冠心病","风湿性心脏病","慢性阻塞性肺疾病","心肌病"],"answer":2,"explanation":"COPD是慢性肺源性心脏病最主要的病因（缺氧致肺动脉高压）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2196","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺心病急性加重期的首要治疗是？","options":["扩血管","强心","利尿","控制感染、改善呼吸功能"],"answer":3,"explanation":"肺心病加重期以控制感染、保持呼吸道通畅、纠正缺氧为首要，慎用利尿强心。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2197","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肺性脑病的主要表现是？","options":["胸痛","单纯咳嗽加重","咯血","神志改变（嗜睡、烦躁、昏迷）"],"answer":3,"explanation":"肺性脑病由缺氧和CO₂潴留引起，表现为神志精神改变，是肺心病死亡主要原因。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2198","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"呼吸衰竭最常见的病因是？","options":["肺水肿","肺炎","气胸","慢性阻塞性肺疾病"],"answer":3,"explanation":"COPD是呼吸衰竭最常见病因（通气与换气功能障碍）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2199","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"呼吸衰竭患者氧疗的原则（Ⅱ型）是？","options":["低浓度持续吸氧（25-33%）","高浓度吸氧","间断吸氧","不需吸氧"],"answer":0,"explanation":"Ⅱ型呼衰靠低氧刺激呼吸中枢，高浓度氧抑制呼吸致CO₂潴留加重，用低浓度持续氧疗。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2200","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌术的原则不包括？","options":["手术人员可佩戴有菌手套操作","手术区消毒铺巾","器械物品灭菌","操作规程严格"],"answer":0,"explanation":"无菌术要求手术人员洗手穿无菌衣、戴无菌手套，不能带菌操作。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2201","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"手术区皮肤消毒的范围应包括切口周围？","options":["50cm","5cm","30cm","至少15cm"],"answer":3,"explanation":"手术区消毒范围至少包括切口周围15cm，如有延长切口的可能应扩大消毒范围。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2202","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"外科洗手后，双手应保持的姿势是？","options":["随意放置","自然下垂","交叉放于背后","拱手置于胸前"],"answer":3,"explanation":"洗手后双手拱于胸前，不再接触有菌物品，避免污染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2203","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"手术切口感染最常见的病原菌是？","options":["大肠埃希菌","金黄色葡萄球菌","厌氧菌","铜绿假单胞菌"],"answer":1,"explanation":"手术切口感染以金黄色葡萄球菌最常见（皮肤常驻菌）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2204","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"等渗性缺水的特点是？","options":["失水多于失钠","水和钠成比例丢失，血钠正常","失钠多于失水","血钠<130mmol/L"],"answer":1,"explanation":"等渗性缺水（急性缺水）水钠等比例丢失，血钠135-145mmol/L正常，外科最常见。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2205","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高渗性缺水的特点是？","options":["失水多于失钠，血钠>145mmol/L","水钠等比例丢失","血钠<130mmol/L","尿量增多"],"answer":0,"explanation":"高渗性缺水（原发性缺水）失水多于失钠，口渴明显、尿少、比重高。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2206","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"低渗性缺水的特点是？","options":["尿比重增高","口渴明显","血钠>150mmol/L","失钠多于失水，血钠<135mmol/L"],"answer":3,"explanation":"低渗性缺水失钠多于失水，早期无口渴、尿少晚期明显、易休克。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2207","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"低钾血症的心电图典型表现是？","options":["QRS增宽","T波高尖","T波低平、U波增高","P波消失"],"answer":2,"explanation":"低钾血症心电图：T波低平或倒置、U波出现或增高、ST段下移。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2208","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高钾血症的心电图典型表现是？","options":["P-R间期缩短","U波增高","T波低平","T波高尖"],"answer":3,"explanation":"高钾血症心电图：T波高尖、Q-T间期延长，重者QRS增宽、室颤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2209","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"补钾的原则不包括？","options":["见尿补钾（尿量>40ml/h）","浓度不超过0.3%","可直接静脉推注","速度不宜过快"],"answer":2,"explanation":"补钾禁止静脉推注，浓度<0.3%、速度<0.75g/h、见尿补钾、每日总量<6-8g。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2210","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"代谢性酸中毒的典型表现是？","options":["呼吸正常","呼吸浅慢","呼吸深大（Kussmaul呼吸）","发绀"],"answer":2,"explanation":"代谢性酸中毒呼吸代偿性深大（酸中毒大呼吸），呼出CO2增多。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2211","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"代谢性碱中毒的常见原因是？","options":["休克","腹泻","大量呕吐（胃酸丢失）","肾功能不全"],"answer":2,"explanation":"大量呕吐丢失胃酸（H+、Cl-）致代谢性碱中毒，伴低钾低氯。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2212","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"休克的基本病理生理改变是？","options":["心输出量增加","血容量增加","有效循环血量减少、微循环障碍","血管扩张（所有类型）"],"answer":2,"explanation":"休克本质是有效循环血量锐减和组织灌注不足，微循环障碍是共同环节。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2213","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"休克早期（代偿期）的表现是？","options":["精神紧张、面色苍白、脉压缩小","血压明显下降","意识丧失","无尿"],"answer":0,"explanation":"休克早期血压可正常，表现为烦躁、面色苍白、心率增快、脉压缩小（<30mmHg）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2214","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"休克监测中最简单有效的指标是？","options":["血气","中心静脉压","尿量","乳酸"],"answer":2,"explanation":"尿量反映肾脏灌注，是休克监测最简单有效的指标（<25ml/h提示灌注不足）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2215","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"休克患者补液的首要原则是？","options":["先纠酸","快速补充血容量","先强心","先利尿"],"answer":1,"explanation":"休克治疗首要措施是补充血容量（先晶体后胶体），恢复有效循环。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2216","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"中心静脉压（CVP）正常值为？","options":["15-20 cmH₂O","0-5 cmH₂O","5-12 cmH₂O","20-30 cmH₂O"],"answer":2,"explanation":"CVP正常5-12cmH₂O；低血压+低CVP提示血容量不足，需快速补液。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2217","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"低血容量休克补充血容量首选的液体是？","options":["全血","平衡盐溶液（晶体液）","白蛋白","右旋糖酐"],"answer":1,"explanation":"休克补液先晶体（平衡盐溶液）后胶体，晶体液可快速恢复血容量。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2218","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"感染性休克（脓毒性休克）的治疗关键是？","options":["仅补液","控制感染+液体复苏","仅用升压药","仅用激素"],"answer":1,"explanation":"感染性休克需同时控制感染（抗生素、引流）和液体复苏，必要时血管活性药。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2219","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"失血性休克输血的指征是？","options":["任何失血","失血量超过血容量的20-30%（Hb<70g/L）","失血<10%","仅慢性贫血"],"answer":1,"explanation":"失血>20-30%或Hb<70g/L需输血；轻度失血用晶体液补充即可。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2220","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"休克指数（脉搏/收缩压）为1.0提示？","options":["无失血","失血<10%","失血>50%","失血约20-30%"],"answer":3,"explanation":"休克指数=脉率/收缩压：0.5正常，1.0提示失血20-30%，1.5提示失血30-50%。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2221","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"麻醉前用药的目的不包括？","options":["镇静、镇痛","增加麻醉药用量","抑制腺体分泌","预防不良反应"],"answer":1,"explanation":"麻醉前用药为镇静、镇痛、抑制分泌、预防不良反应，不增加麻醉药用量。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2222","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"全身麻醉最重要的环节是？","options":["维持呼吸道通畅、保证氧供","监测血压","补液","体位"],"answer":0,"explanation":"全麻管理核心是气道管理和呼吸支持，防止缺氧和CO2蓄积。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2223","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气管内插管的主要目的是？","options":["减少麻醉药用量","保持呼吸道通畅、便于控制呼吸","便于手术操作","防止误吸（唯一目的）"],"answer":1,"explanation":"气管插管保持气道通畅、便于机械通气和防止误吸，是全麻重要保障。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2224","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"局部麻醉药中毒的早期表现是？","options":["口周麻木、头晕、耳鸣","昏迷","抽搐（晚期）","呼吸停止（晚期）"],"answer":0,"explanation":"局麻药中毒早期：口周麻木、头晕、耳鸣、言语不清，重者抽搐、惊厥。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2225","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"局麻药中加入肾上腺素的目的是？","options":["止痛","增强麻醉效果（直接）","预防过敏","延缓吸收、延长作用时间、减少中毒"],"answer":3,"explanation":"肾上腺素收缩局部血管，延缓局麻药吸收，延长作用、减少全身中毒。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2226","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰麻（蛛网膜下腔阻滞）最常见的并发症是？","options":["尿潴留","头痛","低血压（交感神经阻滞）","感染"],"answer":2,"explanation":"腰麻阻滞交感神经致血管扩张、血压下降，是最常见并发症。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2227","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰麻后头痛的特点是？","options":["持续一周以上","平卧加重","与体位无关","坐起或站立时加重、平卧减轻"],"answer":3,"explanation":"腰麻后头痛为低颅压性头痛，坐起加重、平卧缓解，多在一周内自愈。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2228","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"硬膜外麻醉最严重的并发症是？","options":["低血压","全脊髓麻醉","尿潴留","感染"],"answer":1,"explanation":"硬膜外导管误入蛛网膜下腔致全脊髓麻醉（呼吸停止、意识丧失），最严重。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2229","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"创伤急救的基本原则是？","options":["先搬运","先处理骨折","先包扎","先救命后治伤（先处理危及生命的问题）"],"answer":3,"explanation":"创伤急救优先处理危及生命的问题（气道、呼吸、循环），再处理其他损伤。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2230","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"现场心肺复苏的步骤顺序是？","options":["胸外按压→开放气道→人工呼吸（C-A-B）","A-B-C","开放气道→按压→呼吸","人工呼吸→按压"],"answer":0,"explanation":"现行指南强调先胸外按压（C），再开放气道（A）、人工呼吸（B）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2231","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸外按压的部位是？","options":["心尖部","胸骨中下1/3交界处（两乳头连线中点）","胸骨上段","左胸部"],"answer":1,"explanation":"按压部位为胸骨中下段（两乳头连线中点），深度5-6cm，频率100-120次/分。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2232","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"单人心肺复苏时按压与人工呼吸的比例是？","options":["30:2","15:2","5:1","10:1"],"answer":0,"explanation":"单人或双人施救成人CPR按压与通气比均为30:2。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2233","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"止血带止血的注意事项不包括？","options":["每小时放松1-2分钟","连续使用不超过1小时（可延长至2小时）","记录上止血带时间","上臂中1/3禁用（桡神经）"],"answer":1,"explanation":"止血带连续使用一般不超过1小时，最长不超过2-3小时（每小时放松1-2分钟）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2234","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤面积计算（中国九分法）中，头颈部占？","options":["18%","6%","12%","9%"],"answer":3,"explanation":"九分法：头颈9%（发部3、面部3、颈部3）、双上肢18%、躯干27%、双下肢46%。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2235","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤面积计算中，双上肢占？","options":["46%","9%","27%","18%"],"answer":3,"explanation":"双上肢18%（双手5、双前臂6、双上臂7）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2236","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤面积计算中，双下肢（含臀部）占？","options":["27%","36%","46%","54%"],"answer":2,"explanation":"双下肢46%（含臀部5%），成年男性；女性双足双臀各多1%。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2237","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤深度判断中，浅Ⅱ度烧伤的特点是？","options":["无水疱、干燥","水疱、剧痛、创面红润（真皮浅层）","焦痂形成","痛觉消失"],"answer":1,"explanation":"浅Ⅱ度伤及真皮浅层，水疱大、剧痛、创面红肿，1-2周愈合不留瘢痕。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2238","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"深Ⅱ度烧伤的特点是？","options":["焦痂、无痛","剧痛、水疱大","痛觉迟钝、创面红白相间（真皮深层）","仅红斑"],"answer":2,"explanation":"深Ⅱ度伤及真皮深层，痛觉迟钝、水疱小、创面红白相间，3-4周愈合多留瘢痕。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2239","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"Ⅲ度烧伤的特点是？","options":["焦痂、蜡白或炭化、痛觉消失","水疱、剧痛","红斑、灼痛","水疱小、痛觉迟钝"],"answer":0,"explanation":"Ⅲ度伤及皮肤全层甚至皮下，创面蜡白/焦黄/炭化、干燥无水疱、痛觉消失，需手术植皮。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2240","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤休克补液计算中，第一个24小时补液量（成人）为？","options":["固定3000ml","烧伤面积×体重×0.5ml","烧伤面积×体重×3ml","烧伤面积%×体重kg×1.5ml+基础需要量2000ml"],"answer":3,"explanation":"第一个24小时补液：每1%面积每公斤体重1.5ml（胶体+晶体）+基础水分2000ml。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2241","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤创面处理的原则不包括？","options":["浅度创面防止感染","深度烧伤尽早切痂植皮","创面清洁","深度创面长期保守换药（必然）"],"answer":1,"explanation":"深Ⅱ度和Ⅲ度烧伤应尽早切（削）痂植皮，不宜长期保守换药。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2242","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"冻伤的急救措施是？","options":["用力揉搓","用38-42℃温水复温","火烤","雪搓"],"answer":1,"explanation":"冻伤用温水（38-42℃）快速复温，禁用火烤、雪搓、用力揉搓。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2243","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"毒蛇咬伤的急救措施是？","options":["热敷","立即切开伤口大范围切除","近心端绑扎、清创排毒、注射抗蛇毒血清","饮酒"],"answer":2,"explanation":"毒蛇咬伤：肢体近心端绑扎（每15-20分钟放松1-2分钟）、伤口冲洗、抗蛇毒血清。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2244","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"破伤风的预防措施不包括？","options":["彻底清创","伤口深部缝合包扎（厌氧环境）","注射破伤风抗毒素（TAT）","接种破伤风类毒素"],"answer":1,"explanation":"破伤风梭菌为厌氧菌，深部缝合包扎造成厌氧环境利于繁殖，应敞开伤口。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2245","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"破伤风发作的典型表现是？","options":["感觉减退","弛缓性瘫痪","牙关紧闭、苦笑面容、角弓反张","意识丧失（早期）"],"answer":2,"explanation":"破伤风典型：牙关紧闭、苦笑面容、颈项强直、角弓反张（骨骼肌强直性痉挛），神志清楚。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2246","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"破伤风患者病室环境的要求是？","options":["强光照射","避光、安静、减少刺激","嘈杂环境","频繁探视"],"answer":1,"explanation":"破伤风痉挛可因声光刺激诱发，病室应避光、安静、减少刺激。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2247","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气性坏疽的病原体是？","options":["大肠埃希菌","破伤风梭菌","金黄色葡萄球菌","产气荚膜梭菌"],"answer":3,"explanation":"气性坏疽由产气荚膜梭菌等厌氧菌引起，组织气肿、坏死、恶臭。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2248","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气性坏疽的处理原则是？","options":["截肢（唯一方法）","保守换药","紧急手术切开减压、切除坏死组织、大剂量抗生素","热敷"],"answer":2,"explanation":"气性坏疽需紧急手术（切开引流、切除坏死组织、敞开伤口）+大剂量青霉素。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2249","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性阑尾炎最重要的病因是？","options":["饮食不当","阑尾腔梗阻（粪石等）+细菌感染","遗传","免疫因素"],"answer":1,"explanation":"阑尾腔梗阻后细菌繁殖、腔内压力升高，是急性阑尾炎的主要发病机制。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2250","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性阑尾炎腹痛的特点是？","options":["持续性左上腹痛","转移性右下腹痛","阵发性绞痛无固定点","全腹痛"],"answer":1,"explanation":"70-80%患者有转移性右下腹痛：先上腹或脐周，数小时后转移固定于右下腹。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2251","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性阑尾炎穿孔后弥漫性腹膜炎最主要的体征是？","options":["肠鸣音亢进","仅麦氏点压痛","全腹压痛、反跳痛及肌紧张","移动性浊音阳性"],"answer":2,"explanation":"阑尾穿孔后炎症扩散至全腹，出现全腹压痛、反跳痛和肌紧张等腹膜刺激征。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2252","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性阑尾炎出现腹肌紧张、反跳痛提示？","options":["单纯性阑尾炎","阑尾穿孔（腹膜炎）","慢性阑尾炎","阑尾周围脓肿（早期）"],"answer":1,"explanation":"腹膜刺激征（肌紧张、反跳痛）提示阑尾穿孔并发急性腹膜炎。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2253","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"阑尾周围脓肿的处理原则是？","options":["观察","立即手术切除阑尾","立即引流+切除","先抗感染、脓肿局限后择期手术（3个月后）"],"answer":3,"explanation":"阑尾周围脓肿先行抗感染+穿刺引流，炎症消退3个月后择期切除阑尾。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2254","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹外疝最常见的类型是？","options":["腹股沟斜疝","腹股沟直疝","股疝","脐疝"],"answer":0,"explanation":"腹股沟斜疝最常见（占腹股沟疝的85-95%），多见于儿童和青壮年。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2255","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹股沟斜疝与直疝的鉴别要点是？","options":["斜疝经内环突出、可进入阴囊；直疝经直疝三角突出、不进阴囊","斜疝多见于老年人","直疝可进入阴囊","无区别"],"answer":0,"explanation":"斜疝经内环、腹股沟管进入阴囊（儿童青壮年多见）；直疝经直疝三角突出、不进阴囊（老年人多见）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2256","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹外疝发生嵌顿的紧急处理是？","options":["及时手法复位或急诊手术","观察等待","热敷","口服止痛药"],"answer":0,"explanation":"嵌顿疝超过3-4小时或手法复位失败，需急诊手术防止肠坏死。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2257","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腹股沟疝术后应避免？","options":["咳嗽时按压伤口","早期下床活动（根据术式）","3个月内重体力劳动","保持大便通畅"],"answer":2,"explanation":"疝修补术后3个月内避免重体力劳动和剧烈运动，防止复发。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2258","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆石症按部位分为？","options":["大结石、小结石","胆固醇结石、胆色素结石","单发结石、多发结石","胆囊结石、肝外胆管结石、肝内胆管结石"],"answer":3,"explanation":"胆石按部位分：胆囊结石、肝外胆管结石、肝内胆管结石；按成分分胆固醇、胆色素、混合性。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2259","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆囊结石的典型表现是？","options":["无痛性黄疸","持续性钝痛","进食油腻后右上腹阵发性绞痛（胆绞痛）","腹泻"],"answer":2,"explanation":"胆囊结石典型为胆绞痛：进食油腻后右上腹阵发性绞痛，向右肩背放射。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2260","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆囊结石首选的检查是？","options":["口服胆囊造影","CT","MRI","腹部超声"],"answer":3,"explanation":"超声对胆囊结石诊断准确率>95%，是首选检查。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2261","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆囊结石有症状者的首选治疗是？","options":["腹腔镜胆囊切除术","溶石治疗","观察","体外碎石"],"answer":0,"explanation":"有症状的胆囊结石首选腹腔镜胆囊切除术（LC），是金标准。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2262","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性胆囊炎的典型体征是？","options":["麦氏点压痛","Murphy征阳性","移动性浊音","肝掌"],"answer":1,"explanation":"急性胆囊炎：右上腹压痛、Murphy征阳性（深吸气时因疼痛而中止吸气）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2263","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性梗阻性化脓性胆管炎（AOSC）的典型表现是？","options":["单纯发热","Charcot三联征","无痛性黄疸","Reynolds五联征（腹痛、寒战高热、黄疸、休克、神经中枢症状）"],"answer":3,"explanation":"AOSC（急性重症胆管炎）：Charcot三联征（腹痛、寒战高热、黄疸）+休克+神经中枢症状=Reynolds五联征。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2264","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"Charcot三联征是指？","options":["腹痛、呕吐、黄疸","腹痛、寒战高热、黄疸","发热、皮疹、关节痛","腹痛、腹泻、便血"],"answer":1,"explanation":"Charcot三联征提示胆管炎（胆管结石梗阻+感染）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2265","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胆道蛔虫病的典型表现是？","options":["发热为主","持续剧烈腹痛伴腹膜刺激征","无痛性黄疸","阵发性钻顶样绞痛（剑突下），症状重体征轻"],"answer":3,"explanation":"胆道蛔虫：剑突下阵发性钻顶样绞痛，间歇期如常人（症状与体征不符）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2266","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肠梗阻的典型表现是？","options":["腹泻","腹痛、呕吐、腹胀、停止排气排便（四大症状）","便血","发热"],"answer":1,"explanation":"肠梗阻四大症状：阵发性绞痛、呕吐、腹胀、停止排气排便。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2267","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"机械性肠梗阻与麻痹性肠梗阻的鉴别是？","options":["无区别","机械性肠鸣音消失","麻痹性肠鸣音亢进","机械性肠鸣音亢进（气过水声）；麻痹性肠鸣音消失"],"answer":3,"explanation":"机械性肠梗阻肠鸣音亢进（气过水声、金属音）；麻痹性（腹膜炎、术后）肠鸣音消失。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2268","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"绞窄性肠梗阻的特点是？","options":["阵发性绞痛（单纯）","腹痛持续剧烈、腹膜刺激征、血性腹水","呕吐轻","腹胀轻"],"answer":1,"explanation":"绞窄性肠梗阻有血运障碍：腹痛持续剧烈、腹膜刺激征、血性渗出、休克，需急诊手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2269","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肠梗阻的治疗原则是？","options":["口服泻药","立即手术（所有类型）","大量进食","禁食胃肠减压、纠正水电解质紊乱、解除梗阻"],"answer":3,"explanation":"肠梗阻基础治疗：禁食、胃肠减压、补液纠酸，单纯性可保守，绞窄性手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2270","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性乳腺炎最常见的病原菌是？","options":["链球菌","金黄色葡萄球菌","大肠埃希菌","厌氧菌"],"answer":1,"explanation":"急性乳腺炎（哺乳期）以金黄色葡萄球菌最常见，经乳头破损侵入。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2271","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性乳腺炎的好发人群是？","options":["青春期女性","老年女性","产后3-4周的初产妇","男性"],"answer":2,"explanation":"急性乳腺炎多见于产后3-4周初产妇，乳汁淤积+细菌侵入。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2272","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性乳腺炎形成脓肿后的处理是？","options":["切开引流（放射状切口）","继续哺乳","热敷","抗生素（唯一）"],"answer":0,"explanation":"乳腺脓肿需及时切开引流（放射状切口避免损伤乳管），患侧暂停哺乳。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2273","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌最常见的首发表现是？","options":["无痛性单发乳房肿块","乳头溢液","乳房疼痛","皮肤红肿"],"answer":0,"explanation":"乳腺癌多为无痛性单发肿块（质硬、边界不清、活动度差），多位于外上象限。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2274","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌酒窝征的机制是？","options":["皮肤感染","淋巴水肿","肿瘤侵犯乳房悬韧带（Cooper韧带）使其缩短","肿瘤直接侵犯皮肤"],"answer":2,"explanation":"肿瘤侵犯Cooper韧带使其缩短，牵拉皮肤凹陷形成酒窝征。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2275","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌橘皮样变的机制是？","options":["皮肤感染","Cooper韧带受侵","癌细胞堵塞皮下淋巴管，淋巴水肿","血管扩张"],"answer":2,"explanation":"癌细胞堵塞真皮淋巴管致淋巴水肿，毛囊凹陷，皮肤呈橘皮样。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2276","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌淋巴转移最常见的部位是？","options":["腹股沟","对侧腋窝","锁骨上（首先）","同侧腋窝淋巴结"],"answer":3,"explanation":"乳腺癌淋巴转移首先至同侧腋窝淋巴结。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2277","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌的确诊方法是？","options":["MRI","钼靶","超声","穿刺或切除活检（病理）"],"answer":3,"explanation":"乳腺癌确诊依赖病理（穿刺活检或切除活检），钼靶、超声为筛查手段。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2278","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"乳腺癌内分泌治疗适用于？","options":["三阴性乳腺癌","所有患者","HER2阳性者","雌激素受体（ER）或孕激素受体（PR）阳性者"],"answer":3,"explanation":"ER/PR阳性者行内分泌治疗（他莫昔芬、芳香化酶抑制剂），HER2阳性用靶向药。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2279","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺功能亢进症手术治疗的适应证不包括？","options":["中重度甲亢、腺体大","青少年患者（首选）","压迫症状","怀疑恶变"],"answer":1,"explanation":"青少年甲亢首选抗甲状腺药物；手术适用于腺体大、压迫症状、怀疑恶变、药物治疗无效或复发者。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2280","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺大部切除术最严重的并发症是？","options":["声音嘶哑","呼吸困难和窒息（出血压迫、喉头水肿）","手足抽搐","甲状腺危象"],"answer":1,"explanation":"术后48小时内呼吸困难和窒息（出血、喉头水肿、气管塌陷）最危急，需紧急处理。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2281","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺大部切除术后声音嘶哑提示？","options":["喉上神经外支损伤","喉上神经内支损伤","喉返神经损伤","甲状旁腺损伤"],"answer":2,"explanation":"喉返神经损伤致声音嘶哑（单侧）或失声、窒息（双侧）；喉上神经内支损伤致饮水呛咳。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2282","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺术后手足抽搐提示？","options":["喉返神经损伤","甲状旁腺损伤（低钙）","喉上神经损伤","出血"],"answer":1,"explanation":"甲状旁腺误伤致低钙血症，表现为手足抽搐，用葡萄糖酸钙治疗。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2283","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"甲状腺癌最常见的类型是？","options":["髓样癌","滤泡状癌","乳头状癌","未分化癌"],"answer":2,"explanation":"甲状腺癌以乳头状癌最常见（约80-90%），生长慢、预后好。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2284","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折的专有体征是？","options":["疼痛、肿胀","畸形、异常活动、骨擦音（感）","功能障碍","淤血"],"answer":1,"explanation":"骨折三大专有体征：畸形、异常活动、骨擦音/骨擦感，具备其一即可确诊。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2285","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折急救的原则是？","options":["热敷","立即复位","立即手术","固定、止血、包扎、搬运（先救命后治伤）"],"answer":3,"explanation":"骨折急救：先处理休克和危及生命的损伤，妥善固定（不盲目复位），正确搬运。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2286","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折早期并发症不包括？","options":["坠积性肺炎（晚期）","休克","脂肪栓塞","骨筋膜室综合征"],"answer":0,"explanation":"坠积性肺炎为长期卧床的晚期并发症；早期并发症有休克、脂肪栓塞、骨筋膜室综合征、血管神经损伤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2287","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨筋膜室综合征的典型表现是？","options":["活动自如","无痛","皮温升高（早期）","剧痛、被动牵拉痛、感觉异常、皮肤苍白（5P征）"],"answer":3,"explanation":"骨筋膜室综合征5P征：疼痛（pain）、苍白（pallor）、感觉异常（paresthesia）、麻痹（paralysis）、无脉（pulselessness），需紧急切开减压。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2288","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折愈合血肿机化期的时间是？","options":["伤后1年","伤后2-3天","伤后2-3个月","伤后2-3周"],"answer":3,"explanation":"骨折愈合过程：血肿机化期（2-3周）→原始骨痂形成期（4-8周）→骨痂改造塑形期。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2289","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨折临床愈合的标准不包括？","options":["局部仍有异常活动","局部无压痛、无纵向叩击痛","局部无异常活动","X线显示骨折线模糊、有连续性骨痂"],"answer":0,"explanation":"临床愈合标准：无压痛、无纵向叩痛、无异常活动、X线骨折线模糊有骨痂、功能恢复。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2290","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"Colles骨折（桡骨远端）的典型畸形是？","options":["垂腕","爪形手","餐叉样和枪刺样畸形","方肩"],"answer":2,"explanation":"Colles骨折（伸直型桡骨远端骨折）典型畸形为餐叉样和枪刺样畸形。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2291","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肩关节脱位的典型表现是？","options":["餐叉畸形","方肩畸形、Dugas征（搭肩试验）阳性","爪形手","下肢短缩"],"answer":1,"explanation":"肩关节前脱位：方肩畸形、关节盂空虚、Dugas征阳性（患侧手搭对侧肩部肘不能贴胸）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2292","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"髋关节脱位（后脱位）的典型畸形是？","options":["患肢屈曲、内收、内旋、短缩","外展外旋","伸直位","无畸形"],"answer":0,"explanation":"髋关节后脱位：患肢屈曲内收内旋短缩畸形，大转子向上移位。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2293","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰椎间盘突出症最常见的突出部位是？","options":["L4-5和L5-S1","L1-2","L2-3","L3-4"],"answer":0,"explanation":"腰椎间盘突出症最常见于L4-5和L5-S1间隙，压迫L5和S1神经根。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2294","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰椎间盘突出症的主要表现是？","options":["下肢无力（唯一）","单纯腰痛","腰痛伴坐骨神经痛（下肢放射痛）","大小便失禁（早期）"],"answer":2,"explanation":"典型表现：腰痛+坐骨神经痛（沿臀部、大腿后侧、小腿放射），直腿抬高试验阳性。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2295","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"腰椎间盘突出症最重要的体征是？","options":["Babinski征","Kernig征","直腿抬高试验及加强试验阳性","肌张力增高"],"answer":2,"explanation":"直腿抬高试验（<60°出现放射痛）及加强试验阳性是腰椎间盘突出症的重要体征。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2296","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"颈椎病最常见的类型是？","options":["椎动脉型","脊髓型","神经根型","交感神经型"],"answer":2,"explanation":"神经根型颈椎病最常见（50-60%），表现为颈肩痛伴上肢放射痛、麻木。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2297","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脊髓型颈椎病的特点是？","options":["单纯颈肩痛","下肢无力、踩棉花感、病理征阳性","头晕","耳鸣"],"answer":1,"explanation":"脊髓型颈椎病最严重：四肢无力、行走踩棉花感、腱反射亢进、病理征阳性，多需手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2298","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性血源性骨髓炎的好发部位是？","options":["脊柱","扁骨","长骨干骺端（胫骨上端、股骨下端）","颅骨"],"answer":2,"explanation":"急性血源性骨髓炎多见于儿童长骨干骺端（血流缓慢易滞留细菌）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2299","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性血源性骨髓炎早期诊断最有价值的检查是？","options":["局部穿刺抽脓（细菌培养）","X线（早期正常）","CT","MRI（早期敏感）"],"answer":0,"explanation":"发病早期X线无改变（2周后出现），局部穿刺抽脓+培养可早期确诊。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2300","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"骨肿瘤的好发年龄与部位是？","options":["婴幼儿颅骨","老年人扁骨","中年人脊柱（唯一）","青少年长骨干骺端（骨肉瘤）"],"answer":3,"explanation":"骨肉瘤好发于青少年长骨干骺端（股骨下端、胫骨上端），Codman三角和日光射线征为特征。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2301","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前列腺增生症最早出现的症状是？","options":["尿失禁","排尿困难","血尿","尿频（尤其夜尿增多）"],"answer":3,"explanation":"前列腺增生最早症状为尿频（夜尿增多），进行性排尿困难为最重要表现。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2302","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前列腺增生最重要的表现是？","options":["尿频","进行性排尿困难","血尿","尿潴留"],"answer":1,"explanation":"前列腺增生（老年男性）进行性排尿困难（排尿迟缓、尿线细、滴沥）为最重要症状。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2303","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前列腺增生急性尿潴留的处理是？","options":["立即手术","导尿（必要时留置）","热敷（唯一）","大量饮水"],"answer":1,"explanation":"急性尿潴留先导尿（必要时留置导尿管），择期处理增生。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2304","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"泌尿系结石的主要表现是？","options":["脓尿","无痛性血尿","肾绞痛伴血尿","蛋白尿"],"answer":2,"explanation":"泌尿系结石：肾绞痛（剧烈阵发性腰痛向下腹放射）伴血尿（镜下或肉眼）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2305","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾绞痛发作时的紧急处理是？","options":["大量补液","立即手术","解痉止痛（阿托品/山莨菪碱+止痛药）","抗生素"],"answer":2,"explanation":"肾绞痛用解痉药（阿托品、山莨菪碱）+止痛药（哌替啶等），多饮水促排石。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2306","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输尿管结石直径小于多少可保守排石？","options":["0.6 cm","1.5 cm","2 cm","3 cm"],"answer":0,"explanation":"结石<0.6cm、光滑、无梗阻感染可保守治疗（多饮水、药物排石）；较大者体外碎石或手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2307","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"膀胱肿瘤最常见的表现是？","options":["脓尿","尿频尿急","排尿困难","无痛性肉眼血尿"],"answer":3,"explanation":"膀胱肿瘤典型表现为间歇性无痛性肉眼血尿（全程）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2308","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾癌的典型三联征是？","options":["尿频、尿急、尿痛","发热、贫血、消瘦","蛋白尿、水肿、高血压","血尿、腰痛、肿块"],"answer":3,"explanation":"肾癌三联征：血尿（最常见）、腰痛、肿块，同时出现者已属晚期。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2309","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"烧伤创面感染最常见的病原菌是？","options":["铜绿假单胞菌和金黄色葡萄球菌","大肠埃希菌","厌氧菌","真菌"],"answer":0,"explanation":"烧伤创面感染以铜绿假单胞菌和金黄色葡萄球菌常见。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2310","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"挤压综合征的主要表现是？","options":["发热","单纯骨折","肢体肿胀、肌红蛋白尿、急性肾损伤","黄疸"],"answer":2,"explanation":"挤压综合征：肢体长时间受压，肌红蛋白尿（酱油色）致急性肾损伤，需碱化尿液。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2311","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"外科感染的特点不包括？","options":["多数为混合感染","多为单一细菌感染","局部表现明显","常需外科处理"],"answer":1,"explanation":"外科感染多为混合感染（多种细菌），局部症状明显，常需手术引流。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2312","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"疖与痈的区别是？","options":["痈为单个毛囊感染","痈为多个相邻毛囊及其所属皮脂腺的感染","疖更严重","无区别"],"answer":1,"explanation":"疖为单个毛囊及皮脂腺感染；痈为多个相邻毛囊的感染，范围大、症状重。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2313","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"危险三角区疖肿挤压的危险是？","options":["淋巴结炎","局部化脓","引起海绵状静脉窦炎（颅内感染）","败血症（必然）"],"answer":2,"explanation":"面部危险三角区疖肿挤压可使细菌经静脉入颅，引起海绵状静脉窦炎，危及生命。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2314","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"丹毒的病原体是？","options":["大肠埃希菌","金黄色葡萄球菌","乙型溶血性链球菌","厌氧菌"],"answer":2,"explanation":"丹毒为皮肤网状淋巴管炎，由乙型溶血性链球菌引起，边界清楚、鲜红色。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2315","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"破伤风的潜伏期一般为？","options":["1天","6-12天","1个月以上（必然）","数小时"],"answer":1,"explanation":"破伤风潜伏期一般6-12天，潜伏期越短病情越重。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2316","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"气胸的分类不包括？","options":["血气胸（分类之一，但非基本类型）","闭合性（单纯性）气胸","交通性（开放性）气胸","张力性（高压性）气胸"],"answer":0,"explanation":"自发性气胸分闭合性、交通性、张力性三类；张力性最危急。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2317","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"张力性气胸的紧急处理是？","options":["吸氧（唯一）","立即手术","观察","立即用粗针头于患侧锁骨中线第2肋间穿刺排气"],"answer":3,"explanation":"张力性气胸（胸膜腔压力持续升高）立即用粗针头在第2肋间锁骨中线穿刺排气减压。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2318","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸腔闭式引流的适应证不包括？","options":["中大量气胸、血胸","少量闭合性气胸（肺压缩<20%）","开放性气胸","张力性气胸"],"answer":1,"explanation":"肺压缩<20%的少量气胸可观察自行吸收，不需闭式引流。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2319","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胸腔闭式引流管的放置位置（排气）是？","options":["患侧锁骨中线第2肋间","腋中线第6-8肋间（排液）","胸骨旁第4肋间","肩胛线第8肋间"],"answer":0,"explanation":"排气于锁骨中线第2肋间；排液于腋中线与腋后线之间第6-8肋间。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2320","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"女性外阴部最易发生炎症的部位是？","options":["卵巢","子宫","输卵管","阴道（前庭大腺等）"],"answer":3,"explanation":"外阴阴道炎症最常见（解剖特点：与外界相通、邻近肛门）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2321","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"成年女性子宫的正常位置是？","options":["前倾前屈位","后倾后屈位","水平位","后倾前屈位"],"answer":0,"explanation":"正常子宫位置为前倾前屈位，依靠韧带（圆韧带、阔韧带等）和盆底组织维持。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2322","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维持子宫正常位置的主要韧带中，防止子宫下垂的是？","options":["子宫圆韧带","子宫主韧带","子宫阔韧带","卵巢固有韧带"],"answer":1,"explanation":"主韧带（宫颈横韧带）固定宫颈水平位置、防止子宫下垂；圆韧带维持前倾，骶子宫韧带维持前屈。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2323","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"防止子宫下垂最重要的韧带是？","options":["卵巢固有韧带","圆韧带","阔韧带","子宫主韧带"],"answer":3,"explanation":"主韧带（宫颈横韧带）固定宫颈、防止子宫下垂，是维持子宫位置最重要的韧带。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2324","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"女性青春期的重要标志是？","options":["身高突增","乳房发育（第二性征最早）","阴毛出现","月经初潮"],"answer":3,"explanation":"月经初潮是女性青春期的重要标志（乳房发育为最早出现的第二性征）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2325","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"女性一生中排卵的次数约为？","options":["100个","400-500个","1000个","50个"],"answer":1,"explanation":"女性一生约排出400-500个成熟卵子（每月1个，约35年生育期）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2326","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"排卵一般发生在下次月经来潮前？","options":["7天","14天左右","21天","28天"],"answer":1,"explanation":"排卵发生在下次月经来潮前14天左右（黄体期固定为14天）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2327","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"月经血的特点是？","options":["黑色","鲜红色、易凝固","暗红色、不凝固（含纤溶酶）","白色"],"answer":2,"explanation":"月经血暗红色、不凝（子宫内膜纤溶酶溶解纤维蛋白），量约20-60ml。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2328","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常月经周期平均为？","options":["35天","21天","28天","14天"],"answer":2,"explanation":"正常月经周期21-35天，平均28天；经期2-8天，平均4-6天。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2329","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"卵巢的功能是？","options":["孕育胎儿","仅分泌激素","仅产生卵子","产生卵子和分泌性激素"],"answer":3,"explanation":"卵巢有生殖功能（排卵）和内分泌功能（分泌雌激素、孕激素等）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2330","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"雌激素的生理作用不包括？","options":["促进子宫内膜增生","使子宫内膜呈分泌期改变","促进第二性征发育","使宫颈黏液稀薄"],"answer":1,"explanation":"分泌期改变由孕激素引起；雌激素使内膜增生、宫颈黏液稀薄拉丝长。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2331","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"孕激素的生理作用是？","options":["促进乳腺管增生（雌激素）","促进子宫内膜增生","使宫颈黏液拉丝长","使增生期子宫内膜转变为分泌期"],"answer":3,"explanation":"孕激素使增生期内膜转为分泌期、宫颈黏液变稠、基础体温升高0.3-0.5℃。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2332","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"受精的部位是？","options":["卵巢","子宫腔","输卵管峡部","输卵管壶腹部"],"answer":3,"explanation":"精子与卵子在输卵管壶腹部受精。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2333","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"受精卵着床的时间是？","options":["受精后1天","受精后6-7天","受精后1个月","受精后14天"],"answer":1,"explanation":"受精卵在受精后6-7天着床（植入子宫内膜）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2334","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠全过程分为？","options":["早期（20周前）","早期（16周前）、中期、晚期","早期（12周末前）、中期（13-27周末）、晚期（28周及以后）","早期（10周前）"],"answer":2,"explanation":"妊娠分期：12周末前为早期，13-27周末为中期，28周及以后为晚期。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2335","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠早期诊断最重要的表现是？","options":["停经（育龄妇女）","恶心呕吐","尿频","乳房胀痛"],"answer":0,"explanation":"育龄妇女停经是妊娠最早最重要的症状，结合早孕反应、尿HCG阳性可诊断。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2336","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"早孕反应一般出现在停经后？","options":["4周","2周","12周","6周左右"],"answer":3,"explanation":"早孕反应（恶心、呕吐、嗜睡等）多在停经6周左右出现，12周左右自行消失。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2337","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常胎心率为？","options":["110-160次/分","80-100次/分","160-180次/分","100-120次/分"],"answer":0,"explanation":"正常胎心110-160次/分；<110或>160提示胎儿窘迫。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2338","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常足月妊娠的孕周是？","options":["28-36周","37-42周","42周以上","20-28周"],"answer":1,"explanation":"37-42周为足月妊娠；<37周为早产，≥42周为过期妊娠。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2339","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"预产期的计算方法（末次月经第一天）是？","options":["月份减3或加9，日期加7","月份加3，日期加7","月份减3，日期减7","月份加9，日期加14"],"answer":0,"explanation":"预产期（EDC）：末次月经第一天月份减3或加9、日期加7。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2340","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠期母体血容量增加的高峰时间是？","options":["妊娠40周","妊娠12周","妊娠32-34周","妊娠20周"],"answer":2,"explanation":"血容量妊娠6-8周开始增加，32-34周达高峰（增加30-45%），心脏负担最重。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2341","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产前检查开始的时间是？","options":["分娩前","妊娠28周","妊娠32周","确诊早孕时开始"],"answer":3,"explanation":"确诊早孕即开始首次产检，之后按孕周定期检查（孕中期每4周一次等）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2342","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"推算预产期时，末次月经为2026年3月10日，预产期是？","options":["2026年12月17日","2026年12月10日","2026年11月17日","2027年1月10日"],"answer":0,"explanation":"3月10日：月份12（3+9）、日期17（10+7），即2026年12月17日。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2343","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎儿窘迫的主要表现是？","options":["胎心率异常（<110或>160次/分）和胎动减少","孕妇血压升高","孕妇腹痛","阴道流血"],"answer":0,"explanation":"胎儿窘迫：胎心异常、胎动减少、羊水污染（胎粪）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2344","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常分娩（枕先露）胎头衔接的时间是？","options":["初产妇预产期前1-2周","临产后（初产妇）","分娩后","妊娠20周"],"answer":0,"explanation":"初产妇胎头衔接（双顶径入骨盆入口）多在预产期前1-2周；经产妇在临产后。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2345","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"枕先露分娩机制的正确顺序是？","options":["衔接→下降→俯屈→内旋转→仰伸→复位及外旋转→胎肩胎身娩出","下降→衔接→俯屈","内旋转→衔接→下降","俯屈→衔接→仰伸"],"answer":0,"explanation":"分娩机制：衔接、下降、俯屈、内旋转、仰伸、复位及外旋转、胎肩及胎体娩出。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2346","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"临产的重要标志是？","options":["胎头下降","见红","破水","规律宫缩（持续30秒以上、间歇5-6分钟）伴宫颈管消失和宫口扩张"],"answer":3,"explanation":"临产标志：规律且逐渐增强的宫缩（30秒/5-6分钟）+宫颈管进行性消失+宫口扩张+胎先露下降。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2347","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"见红一般出现在分娩前？","options":["2周","1小时","1周","24-48小时"],"answer":3,"explanation":"见红（宫颈黏液栓排出混少量血）多在分娩发动前24-48小时出现，是分娩先兆。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2348","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第一产程（宫颈扩张期）初产妇平均需要？","options":["11-12小时","2小时","6-8小时（经产妇）","24小时"],"answer":0,"explanation":"第一产程初产妇11-12小时，经产妇6-8小时；第二产程初产妇不超过2小时。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2349","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第二产程（胎儿娩出期）初产妇不应超过？","options":["6小时","30分钟","4小时","2小时"],"answer":3,"explanation":"第二产程初产妇≤2小时（硬膜外麻醉≤3小时），经产妇≤1小时。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2350","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"第三产程（胎盘娩出期）一般需要？","options":["3分钟","2小时","1小时","5-15分钟，不超过30分钟"],"answer":3,"explanation":"第三产程5-15分钟，超过30分钟为胎盘滞留，需人工剥离。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2351","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎盘剥离的征象不包括？","options":["脐带自行下降延长","宫体变硬呈球形","宫体变软呈囊性感","阴道少量流血"],"answer":2,"explanation":"胎盘剥离征象：宫体变硬呈球形、脐带外延、阴道少量流血、按压耻骨联合上缘脐带不再回缩。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2352","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后出血的定义是？","options":["产后出血任何时候>1000ml","产后1周出血500ml","产后2小时出血300ml","胎儿娩出后24小时内出血量≥500ml（剖宫产≥1000ml）"],"answer":3,"explanation":"产后出血：胎儿娩出后24小时内阴道分娩出血≥500ml或剖宫产≥1000ml，是我国孕产妇死亡首要原因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2353","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后出血最常见的原因是？","options":["凝血功能障碍","胎盘因素","软产道裂伤","子宫收缩乏力"],"answer":3,"explanation":"产后出血四大原因：宫缩乏力（最常见）、胎盘因素、软产道裂伤、凝血功能障碍。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2354","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后出血宫缩乏力的处理是？","options":["输血（唯一）","立即切除子宫","立即缝合","按摩子宫+宫缩剂（缩宫素）"],"answer":3,"explanation":"宫缩乏力性出血：按摩子宫、应用宫缩剂（缩宫素、麦角新碱等）、宫腔填塞，无效手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2355","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"羊水栓塞的典型表现是？","options":["单纯阴道流血","单纯腹痛","单纯发热","分娩前后突发呼吸困难、发绀、休克、DIC"],"answer":3,"explanation":"羊水栓塞：分娩前后突发呛咳、呼吸困难、发绀、休克、DIC，死亡率极高。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2356","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"羊水栓塞的急救措施不包括？","options":["立即剖宫产（所有患者）","抗过敏（糖皮质激素）","纠正缺氧","抗休克、防治DIC"],"answer":0,"explanation":"羊水栓塞急救：正压给氧、抗过敏、抗休克、防治DIC、必要时产科处理；不是所有患者立即剖宫产。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2357","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"异位妊娠（宫外孕）最常见的部位是？","options":["输卵管（壶腹部）","卵巢","腹腔","宫颈"],"answer":0,"explanation":"异位妊娠以输卵管妊娠最常见（95%左右），其中壶腹部最多。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2358","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输卵管妊娠破裂的主要表现是？","options":["白带增多","单纯恶心","发热","突发下腹撕裂样疼痛+腹腔内出血（休克）"],"answer":3,"explanation":"输卵管妊娠破裂：突发一侧下腹撕裂样疼痛、腹腔内出血（晕厥、休克）、阴道少量流血。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2359","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"异位妊娠保守治疗的条件不包括？","options":["破裂型（腹腔内出血）","未破裂、包块小（<4cm）","血HCG<2000U/L","无腹腔内出血"],"answer":0,"explanation":"破裂型异位妊娠需手术治疗；保守治疗（甲氨蝶呤）适用于未破裂、包块小、HCG低者。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2360","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"流产的分类不包括？","options":["习惯性流产（现称复发性流产，属特殊类型）","先兆流产","难免流产","不全流产"],"answer":0,"explanation":"流产类型：先兆、难免、不全、完全流产；复发性流产为特殊类型（连续3次及以上）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2361","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"先兆流产的表现是？","options":["胚胎组织排出","大量流血+宫口开大","少量阴道流血+轻微腹痛+宫口未开","发热"],"answer":2,"explanation":"先兆流产：少量流血、轻微下腹痛、宫口未开、妊娠组织未排出，可继续妊娠。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2362","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"难免流产的表现是？","options":["无腹痛","宫口未开","少量流血","宫口开大、胚胎组织堵于宫口"],"answer":3,"explanation":"难免流产：宫口已开、妊娠组织堵塞宫口或羊膜囊膨出，流产不可避免。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2363","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠高血压疾病的基本病理生理变化是？","options":["血管扩张","全身小血管痉挛","血液稀释","血容量减少"],"answer":1,"explanation":"妊高症基本病变为全身小动脉痉挛，致各器官缺血（脑、肾、肝、胎盘）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2364","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子痫前期（重度）的诊断标准不包括？","options":["血压≥160/110mmHg","血压160/110mmHg以下","蛋白尿≥2.0g/24h（或++）","伴头痛、视觉障碍等"],"answer":1,"explanation":"重度子痫前期：血压≥160/110mmHg、蛋白尿明显、伴头痛、视觉障碍、上腹痛等。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2365","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子痫发作时的首要处理是？","options":["立即手术","立即终止妊娠（所有患者）","控制抽搐（硫酸镁静注）","口服降压药"],"answer":2,"explanation":"子痫发作：硫酸镁控制抽搐（首选）、镇静、降压、适时终止妊娠。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2366","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"硫酸镁中毒的表现是？","options":["血压升高","膝反射消失、呼吸抑制、心跳停止","抽搐加重","瞳孔散大（早期）"],"answer":1,"explanation":"硫酸镁中毒：膝反射先消失、呼吸抑制、心跳停止，用药前监测膝反射、呼吸、尿量。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2367","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前置胎盘的典型表现是？","options":["腹痛伴流血","妊娠晚期无痛性反复阴道流血","持续性腹痛","胎心异常（早期）"],"answer":1,"explanation":"前置胎盘：妊娠28周后无痛性反复阴道流血（完全性者出血早且多）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2368","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前置胎盘的确诊方法是？","options":["阴道指检（禁止）","超声检查","CT","腹腔镜"],"answer":1,"explanation":"超声是前置胎盘首选确诊方法；禁止肛门检查和阴道指检（防大出血）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2369","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"前置胎盘的处理原则是？","options":["抑制宫缩、止血、纠正贫血、适时终止妊娠","立即剖宫产（所有患者）","阴道分娩（所有患者）","人工破膜"],"answer":0,"explanation":"前置胎盘：期待疗法（抑制宫缩、促胎肺成熟）至36周以上，完全性前置胎盘剖宫产。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2370","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎盘早剥的主要表现是？","options":["持续性腹痛+阴道流血+子宫板状硬","无痛性流血","单纯腰痛","胎心正常（必然）"],"answer":0,"explanation":"胎盘早剥：持续性腹痛、子宫张力高（板状硬）、阴道流血（可无外出血）、胎儿窘迫。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2371","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎盘早剥最严重的并发症是？","options":["产后出血（一般）","DIC和急性肾衰竭","感染","贫血"],"answer":1,"explanation":"胎盘早剥可致DIC、急性肾衰竭、子宫胎盘卒中，危及母儿生命。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2372","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠期糖尿病的筛查时间是？","options":["妊娠12周","妊娠24-28周","妊娠36周","产后"],"answer":1,"explanation":"妊娠24-28周行75g OGTT筛查妊娠期糖尿病（GDM）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2373","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"妊娠期糖尿病对胎儿的影响不包括？","options":["胎儿畸形","巨大儿","巨大儿（相反说法）","新生儿低血糖"],"answer":2,"explanation":"GDM可致巨大儿、畸形、新生儿低血糖、呼吸窘迫等；巨大儿是其影响而非相反。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2374","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎膜早破的表现是？","options":["阴道流血","阴道流液（阵发性或持续性）","腹痛","发热"],"answer":1,"explanation":"胎膜早破：临产前胎膜破裂、阴道流液（咳嗽、按压宫底时加重），需预防感染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2375","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"胎膜早破的处理不包括？","options":["抬高臀部、防止脐带脱垂","立即阴道检查（所有患者）","预防感染","监测胎心"],"answer":1,"explanation":"胎膜早破禁止不必要的阴道检查（防感染），抬高臀部防脐带脱垂，破膜>12小时预防感染。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2376","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脐带脱垂的紧急处理是？","options":["观察","上推胎头、缓解脐带受压、尽快结束分娩","吸氧（唯一）","等待自然分娩"],"answer":1,"explanation":"脐带脱垂：立即抬高臀部、上推先露部缓解压迫、吸氧，尽快剖宫产结束分娩。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2377","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产褥感染最常见的病原体是？","options":["真菌","单纯病毒","厌氧菌和需氧菌混合感染","结核杆菌"],"answer":2,"explanation":"产褥感染多为厌氧菌与需氧菌混合感染（内源性）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2378","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产褥期子宫复旧的表现是？","options":["产后10天子宫降至盆腔（耻骨联合上摸不到）","产后1周降至盆腔","产后1个月仍在腹部","不缩小"],"answer":0,"explanation":"子宫复旧：产后1周缩至孕12周大小，10天降至盆腔内（腹部摸不到）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2379","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"产后恶露的持续时间（血性恶露）是？","options":["1个月","1天","2周","3-4天"],"answer":3,"explanation":"血性恶露3-4天→浆液性恶露约10天→白色恶露约3周，共4-6周。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2380","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"母乳喂养的优点不包括？","options":["提供免疫物质（SIgA）","增加母亲乳腺癌风险","促进子宫收缩","增进母婴感情"],"answer":1,"explanation":"母乳喂养降低母亲乳腺癌、卵巢癌风险，不增加。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2381","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"初乳的特点是？","options":["产后7天内的乳汁，含免疫球蛋白多","产后1个月的乳汁","脂肪多","蛋白质少"],"answer":0,"explanation":"初乳（产后7天内）质稠、含SIgA等免疫物质多，对新生儿免疫保护重要。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2382","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿脐带护理的原则是？","options":["涂龙胆紫（常规）","湿润包扎","保持干燥、防止污染","频繁牵拉"],"answer":2,"explanation":"脐带残端保持清洁干燥，自然脱落（1-2周），有脓性分泌物及时就医。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2383","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"宫颈癌筛查的首选方法是？","options":["宫颈活检（首选筛查）","宫颈细胞学检查（TCT）+HPV检测","阴道镜（首选筛查）","血CA125"],"answer":1,"explanation":"宫颈癌筛查：TCT+HPV联合筛查；异常者行阴道镜+活检（确诊）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2384","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"宫颈癌的确诊方法是？","options":["HPV检测","TCT","宫颈和宫颈管活组织检查","超声"],"answer":2,"explanation":"宫颈活检（病理）是宫颈癌确诊的金标准。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2385","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"宫颈癌的高危因素不包括？","options":["高危型HPV持续感染","接种HPV疫苗","多个性伴侣","吸烟"],"answer":1,"explanation":"接种HPV疫苗是保护因素；高危型HPV（16、18型）持续感染是主要病因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2386","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫肌瘤最常见的症状是？","options":["月经改变（经量增多、经期延长）","无痛性肿块（唯一）","白带增多","不孕"],"answer":0,"explanation":"子宫肌瘤最常见症状为月经改变（黏膜下肌瘤最明显），可致贫血。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2387","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫肌瘤的治疗原则是？","options":["全部观察","全部手术","全部药物治疗","无症状者观察，症状明显者手术或药物治疗"],"answer":3,"explanation":"子宫肌瘤无症状者定期观察；症状明显、肌瘤大或生长快者手术（肌瘤剔除或子宫切除）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2388","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"卵巢肿瘤最常见的并发症是？","options":["破裂","蒂扭转","感染","恶变"],"answer":1,"explanation":"卵巢肿瘤蒂扭转最常见（突然一侧下腹剧痛、恶心呕吐），需急诊手术。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2389","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"卵巢肿瘤蒂扭转的典型表现是？","options":["阴道流血","无痛性包块","突发一侧下腹剧痛伴恶心呕吐、触及包块","发热"],"answer":2,"explanation":"蒂扭转：突发一侧下腹剧痛、持续性绞痛、恶心呕吐、包块压痛，需急诊手术。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2390","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫内膜癌的主要表现是？","options":["闭经","接触性出血（宫颈癌）","痛经","绝经后阴道流血"],"answer":3,"explanation":"子宫内膜癌典型表现：绝经后阴道流血（或围绝经期月经紊乱）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2391","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"子宫内膜癌的高危因素不包括？","options":["早婚早育","肥胖、高血压、糖尿病","不孕不育","长期雌激素刺激"],"answer":0,"explanation":"子宫内膜癌高危：肥胖、高血压、糖尿病（三联征）、不孕、晚绝经、长期雌激素刺激；早婚早育是宫颈癌高危。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2392","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"葡萄胎的主要表现是？","options":["腹痛（唯一）","子宫小于孕周","无阴道流血","停经后阴道流血+子宫异常增大（大于孕周）"],"answer":3,"explanation":"葡萄胎：停经后不规则阴道流血、子宫异常增大（大于孕周）、HCG异常升高。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2393","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"葡萄胎清宫术后随访的重点是？","options":["血HCG定期监测（至少1年）","血常规","超声（唯一）","胸片（唯一）"],"answer":0,"explanation":"葡萄胎术后随访血HCG至正常后至少1年（每周→每2周→每月），避孕1年。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2394","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"计划生育中，宫内节育器（IUD）的避孕原理是？","options":["干扰受精卵着床","抑制排卵","杀灭精子（唯一）","阻断输卵管"],"answer":0,"explanation":"IUD通过局部炎症反应干扰受精卵着床，属宫内避孕。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2395","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"口服避孕药（短效）的主要避孕原理是？","options":["杀灭受精卵","杀灭精子","阻止着床（唯一）","抑制排卵"],"answer":3,"explanation":"复方短效口服避孕药通过抑制排卵、改变宫颈黏液、干扰内膜等综合作用。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2396","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"紧急避孕药的最佳服用时间是？","options":["1周内","无保护性生活后72小时内（越早越好）","1个月内","随时"],"answer":1,"explanation":"紧急避孕药（左炔诺孕酮）应在无保护性生活后72小时内服用，越早效果越好。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2397","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"人工流产术最常见的并发症是？","options":["子宫穿孔（最严重之一）","人工流产综合征（术中疼痛、心动过缓、血压下降）","感染","宫腔粘连"],"answer":1,"explanation":"人工流产综合征（迷走神经反射）最常见；子宫穿孔、漏吸、宫腔粘连等为其他并发症。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2398","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"药物流产（米非司酮+米索前列醇）适用于？","options":["妊娠49天以内","妊娠3个月","妊娠6个月","任何孕周"],"answer":0,"explanation":"药物流产适用于妊娠≤49天（7周内）的健康妇女。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2399","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"输卵管结扎术的时间是？","options":["月经期","月经干净后3-7天（或产后、流产后）","排卵期","妊娠期"],"answer":1,"explanation":"输卵管结扎在月经干净后3-7天（禁性生活）、产后48小时内或流产后进行。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2400","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿是指？","options":["出生后1周内","出生后脐带结扎至28天的婴儿","出生后1个月内（满月）","出生后3天"],"answer":1,"explanation":"新生儿期：脐带结扎至出生后28天（不满4周）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2401","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常新生儿的体重是？","options":["2500-4000g","1500-2000g","4500-5000g","1000-1500g"],"answer":0,"explanation":"正常新生儿出生体重2500-4000g；<2500g为低出生体重儿，>4000g为巨大儿。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2402","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常新生儿出生后身长平均为？","options":["40cm","50cm","60cm","45cm"],"answer":1,"explanation":"新生儿平均身长50cm，1岁时约75cm，2岁时约85-87cm。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2403","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"1岁时小儿体重约为出生时的？","options":["3倍","2倍","4倍","5倍"],"answer":0,"explanation":"出生体重3kg，1岁约10kg（3倍），2岁约12kg。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2404","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2岁至青春期前小儿体重估算公式是？","options":["年龄×2+8（kg）","年龄×3+5","年龄+5","年龄×5"],"answer":0,"explanation":"2-12岁体重=年龄×2+8（kg）；身高=年龄×7+77（cm）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2405","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2-12岁小儿身高的估算公式是？","options":["年龄×7+77（cm）","年龄×5+50","年龄×2+50","年龄×10"],"answer":0,"explanation":"2-12岁身高=年龄×7+77（cm），每年增长约6-7cm。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2406","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿前囟闭合的时间是？","options":["1-1.5岁","出生时","6个月","3岁"],"answer":0,"explanation":"前囟出生时1.5-2cm，1-1.5岁闭合；后囟出生时很小，6-8周内闭合。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2407","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿乳牙萌出的时间是？","options":["2岁","出生时","4-10个月开始","3岁"],"answer":2,"explanation":"乳牙4-10个月萌出（多数6-8个月），2-2.5岁出齐（20颗）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2408","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"2岁小儿的乳牙数目是？","options":["约24颗","约16颗","约20颗","约28颗"],"answer":2,"explanation":"乳牙共20颗，2-2.5岁出齐。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2409","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿生长发育的一般规律不包括？","options":["由上到下","由远到近（相反）","由近到远","由粗到细"],"answer":1,"explanation":"生长发育规律：由上到下、由近到远、由粗到细、由简单到复杂、由低级到高级。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2410","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿运动发育的规律是？","options":["二抬四翻六坐八爬十站周岁走","一月坐二月翻","三月走六月站","周岁爬"],"answer":0,"explanation":"运动发育口诀：二抬（抬头）四翻（翻身）六坐八爬十站周岁走。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2411","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病的好发年龄是？","options":["3个月-2岁婴幼儿","新生儿期","学龄期","青春期"],"answer":0,"explanation":"佝偻病好发于3个月-2岁婴幼儿（生长快、户外活动少）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2412","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病激期的骨骼改变不包括？","options":["方颅（早期表现）","方颅","肋骨串珠","手镯脚镯征"],"answer":0,"explanation":"方颅多见于8-9个月以上（激期）；早期（3-6个月）以颅骨软化为主。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2413","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病早期的表现是？","options":["O型腿","方颅","肋骨串珠","易激惹、多汗、枕秃（神经兴奋性增高）"],"answer":3,"explanation":"佝偻病早期（3个月内）：易激惹、烦躁、多汗、枕秃（非特异性）；骨骼改变在激期。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2414","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性佝偻病的预防措施是？","options":["生后数天开始补充维生素D（400IU/日）并多晒太阳","仅补钙","仅晒太阳","不干预"],"answer":0,"explanation":"预防：新生儿生后数天开始每日补充维生素D 400IU，适当户外活动（晒太阳）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2415","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"维生素D缺乏性手足搐搦症的主要表现是？","options":["高热","惊厥、手足搐搦、喉痉挛（血钙降低）","呕吐","腹泻"],"answer":1,"explanation":"维生素D缺乏性手足搐搦症：血钙降低致惊厥（最常见）、手足搐搦、喉痉挛。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2416","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"营养不良（蛋白质-能量营养不良）最早的表现是？","options":["贫血","水肿","皮下脂肪消失","体重不增或下降"],"answer":3,"explanation":"营养不良最早表现为体重不增或减轻，随后皮下脂肪减少（先腹部）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2417","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"营养不良患儿皮下脂肪减少的顺序是？","options":["四肢→腹部","面部→腹部","腹部→躯干→臀部→四肢→面部","臀部→面部"],"answer":2,"explanation":"皮下脂肪减少顺序：腹部→躯干→臀部→四肢→面部（最后）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2418","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"营养不良患儿最常见的并发症是？","options":["感染（肺炎、腹泻）","营养性贫血","低血糖","水肿"],"answer":1,"explanation":"营养不良易并发营养性贫血、感染、低血糖、维生素缺乏等；贫血最常见。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2419","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻病最常见的病因是？","options":["寄生虫","细菌感染","真菌","轮状病毒感染（秋冬季）"],"answer":3,"explanation":"婴幼儿腹泻以轮状病毒最常见（秋冬季腹泻，蛋花汤样便）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2420","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"轮状病毒肠炎的大便特点是？","options":["黏液便（细菌性）","脓血便","蛋花汤样便、无腥臭味","果酱样便"],"answer":2,"explanation":"轮状病毒肠炎：蛋花汤样或水样便、无腥臭、量多，伴呕吐、发热。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2421","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻重度脱水的主要表现是？","options":["大便次数增多（唯一）","单纯口渴","眼窝明显凹陷、尿量明显减少、皮肤弹性差、精神萎靡","低热"],"answer":2,"explanation":"重度脱水：失水>10%体重，眼窝前囟明显凹陷、皮肤弹性极差、尿量极少、精神萎靡或昏迷。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2422","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻补液的原则是？","options":["先快后慢、先浓后淡、见尿补钾","先慢后快","先补钾后补液","大量补液（无原则）"],"answer":0,"explanation":"补液原则：先快后慢、先浓后淡（先盐后糖）、见尿补钾、抽搐补钙。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2423","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻补钾的浓度是？","options":["0.15-0.3%（不超过0.3%）","0.5%","1%","3%"],"answer":0,"explanation":"小儿补钾浓度0.15-0.3%（40mmol/L以下），速度慢，见尿补钾。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2424","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎最常见的病原体是？","options":["衣原体","支原体","真菌","细菌和病毒（肺炎链球菌常见）"],"answer":3,"explanation":"小儿肺炎以细菌（肺炎链球菌最常见）和病毒为主；支原体肺炎多见于学龄期。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2425","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎的主要表现是？","options":["发热、咳嗽、气促、肺部固定湿啰音","单纯发热","单纯咳嗽无体征","喘息（唯一）"],"answer":0,"explanation":"小儿肺炎：发热、咳嗽、气促、呼吸困难，肺部固定性中细湿啰音。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2426","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎合并心力衰竭的表现不包括？","options":["心率>180次/分","心率减慢","呼吸>60次/分","肝脏短时间内增大"],"answer":1,"explanation":"肺炎合并心衰：心率>180次/分、呼吸>60次/分、肝脏增大、烦躁、发绀加重；心率不减慢。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2427","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎抗生素治疗的原则是？","options":["长期维持","症状消失即停药","单药小剂量","早期、联合、足量、足疗程"],"answer":3,"explanation":"小儿肺炎抗生素：早期、联合、足量、足疗程（体温正常后5-7天，症状体征消失后3天停药）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2428","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"先天性心脏病中最常见的是？","options":["房间隔缺损","室间隔缺损","动脉导管未闭","法洛四联症"],"answer":1,"explanation":"先天性心脏病以室间隔缺损最常见（约30%）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2429","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"法洛四联症的四种畸形不包括？","options":["肺动脉狭窄","房间隔缺损","室间隔缺损","主动脉骑跨"],"answer":1,"explanation":"法洛四联症：肺动脉狭窄、室间隔缺损、主动脉骑跨、右心室肥厚。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2430","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"法洛四联症的主要表现是？","options":["呼吸困难（唯一）","无青紫","水肿","青紫、蹲踞、杵状指"],"answer":3,"explanation":"法洛四联症：青紫（最早出现）、蹲踞、杵状指、缺氧发作。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2431","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"动脉导管未闭的特征性体征是？","options":["舒张期杂音（唯一）","收缩期杂音（唯一）","胸骨左缘第2肋间连续性机器样杂音","心尖区杂音"],"answer":2,"explanation":"动脉导管未闭：胸骨左缘第2肋间连续性机器样杂音，伴周围血管征（水冲脉等）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2432","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"房间隔缺损的典型杂音是？","options":["胸骨左缘第2-3肋间收缩期喷射性杂音（肺动脉瓣区）","连续性杂音","舒张期杂音","心尖区收缩期杂音"],"answer":0,"explanation":"房间隔缺损：肺动脉瓣区（胸骨左缘2-3肋间）收缩期喷射性杂音，第二心音固定分裂。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2433","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"室间隔缺损的典型杂音是？","options":["无杂音","连续性杂音","舒张期杂音","胸骨左缘第3-4肋间粗糙收缩期杂音"],"answer":3,"explanation":"室间隔缺损：胸骨左缘3-4肋间粗糙的全收缩期杂音，伴震颤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2434","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肾小球肾炎的主要表现是？","options":["大量蛋白尿（肾病综合征）","血尿、水肿、高血压","尿频尿急","肾绞痛"],"answer":1,"explanation":"急性肾炎综合征：血尿（几乎均有）、水肿（晨起眼睑）、高血压，病前1-3周有链球菌感染史。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2435","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"急性肾小球肾炎患儿饮食的原则是？","options":["高盐","低盐（水肿高血压明显时）、限制水（严重时）","高蛋白","高脂"],"answer":1,"explanation":"急性肾炎：水肿高血压时低盐饮食（<1g/日），氮质血症时限制蛋白，严重少尿限水。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2436","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"肾病综合征患儿大量蛋白尿的标准是？","options":["尿蛋白+","尿蛋白>50mg/（kg·d）或定性+++以上","尿蛋白++","尿蛋白阴性"],"answer":1,"explanation":"小儿肾病综合征：尿蛋白>50mg/（kg·d）或定性+++以上，血浆白蛋白<25g/L。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2437","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肾病综合征首选的治疗药物是？","options":["利尿剂（唯一）","免疫抑制剂","抗生素","糖皮质激素（泼尼松）"],"answer":3,"explanation":"小儿肾病综合征（多数为微小病变型）首选糖皮质激素，疗效好。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2438","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿生理性黄疸出现的时间是？","options":["生后1个月","生后24小时内","生后1周后","生后2-3天，4-6天达高峰"],"answer":3,"explanation":"生理性黄疸：生后2-3天出现、4-6天高峰、足月儿2周内消退；生后24小时内出现为病理性。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2439","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿病理性黄疸的特点不包括？","options":["生后24小时内出现","黄疸消退后再次出现（属病理性）","足月儿>2周未退","血清胆红素超过正常上限"],"answer":1,"explanation":"病理性黄疸：早（24小时内）、快（胆红素上升快）、高（超过正常值）、久（>2周）、退而复现。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2440","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿胆红素脑病（核黄疸）的好发部位是？","options":["大脑皮层（唯一）","基底核（脑基底节）","小脑","脊髓"],"answer":1,"explanation":"胆红素脑病：未结合胆红素沉积于基底核等，表现为嗜睡、拒奶、尖叫、抽搐。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2441","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿Apgar评分的五项指标是？","options":["体温、脉搏、呼吸、血压、神志","心率、呼吸、肌张力、喉反射、皮肤颜色","哭声、吸吮、拥抱、觅食、握持","体重、身长、头围、囟门、体温"],"answer":1,"explanation":"Apgar评分：心率、呼吸、肌张力、喉反射（弹足底反应）、皮肤颜色，每项0-2分。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2442","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿Apgar评分8-10分表示？","options":["重度窒息","轻度窒息","正常（无窒息）","濒死"],"answer":2,"explanation":"Apgar评分8-10分正常；4-7分轻度（青紫）窒息；0-3分重度（苍白）窒息。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2443","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿窒息复苏的首要步骤是？","options":["胸外按压","清理呼吸道（保持气道通畅）","药物治疗","保暖（唯一）"],"answer":1,"explanation":"新生儿复苏ABCDE：清理呼吸道（A）→建立呼吸（B）→恢复循环（C）→药物（D）→评估（E）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2444","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿窒息复苏胸外按压的指征是？","options":["无指征","出生后立即","心率>100次/分","正压通气30秒后心率<60次/分"],"answer":3,"explanation":"正压通气30秒后心率仍<60次/分，行胸外按压（与正压通气3:1）。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2445","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿败血症最常见的感染途径是？","options":["血行（母体）","呼吸道","消化道","脐部和皮肤黏膜"],"answer":3,"explanation":"新生儿败血症以脐部、皮肤黏膜感染最常见（脐炎、脓疱疮等）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2446","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿破伤风的感染原因是？","options":["消化道","呼吸道","脐带断端处理不当（接生消毒不严）","母乳"],"answer":2,"explanation":"新生儿破伤风（四六风）：接生时脐带断端消毒不严，破伤风梭菌侵入，生后4-7天发病。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2447","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿颅内出血最常见的原因是？","options":["产伤和缺氧","感染","凝血障碍","维生素K缺乏（迟发型）"],"answer":0,"explanation":"新生儿颅内出血以产伤（足月儿）和缺氧（早产儿）为主要原因。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2448","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿硬肿症（寒冷损伤综合征）的主要表现是？","options":["高热","低体温、皮肤硬肿","黄疸","腹泻"],"answer":1,"explanation":"新生儿寒冷损伤综合征：低体温（<35℃）、皮肤硬肿（先下肢后全身）、多器官损害。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2449","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿硬肿症复温的原则是？","options":["逐渐复温（体温每小时升高0.5-1℃）","快速复温（立即）","缓慢复温（每天1℃）","不复温"],"answer":0,"explanation":"新生儿硬肿症复温：逐渐复温，轻中度6-12小时内恢复体温，重度12-24小时。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2450","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿呼吸心跳骤停的复苏按压深度（儿童）是？","options":["约为胸廓前后径的1/3（约5cm）","2cm","8cm","10cm"],"answer":0,"explanation":"儿童CPR按压深度约5cm（胸廓前后径1/3），婴儿约4cm。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2451","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿用药剂量的计算最常用方法是？","options":["按体重计算（kg）","按身高","按年龄直接套用","按体表面积（唯一）"],"answer":0,"explanation":"小儿剂量最常按体重计算；某些药物（化疗药）按体表面积更精确。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2452","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿液体疗法中，等渗性脱水首选补充？","options":["高张液","等张液","2/3张液","1/2张含钠液（如3:2:1液）"],"answer":3,"explanation":"等渗性脱水用1/2张含钠液；低渗性用2/3张；高渗性用1/3张。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2453","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻低钾血症补钾的时间要求是？","options":["不补钾","立即补钾","补液后24小时","见尿后补钾"],"answer":3,"explanation":"见尿（尿量>30ml/h）后补钾，防止高钾血症。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2454","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿高热惊厥的特点是？","options":["任何年龄","6个月-5岁、体温>38.5℃、发作后神志清楚","体温正常时发作","发作后持续昏迷"],"answer":1,"explanation":"高热惊厥：6个月-5岁、发热早期（>38.5℃）发作、持续<10分钟、发作后神志清、无神经系统异常。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2455","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿高热惊厥发作时的紧急处理是？","options":["立即口服退热药","保持呼吸道通畅、防止舌咬伤、降温","立即静脉输液","按压肢体"],"answer":1,"explanation":"惊厥处理：平卧头偏一侧、清理呼吸道、防止舌咬伤（牙垫）、吸氧、退热，必要时止惊药。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2456","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿结核菌素试验（PPD）阳性的判断标准是？","options":["硬结<5mm","硬结直径≥5mm（20mm以上或有水疱为强阳性）","无硬结","仅红斑"],"answer":1,"explanation":"PPD：硬结5-9mm弱阳性（+）、10-19mm阳性（++）、≥20mm或水疱坏死为强阳性（+++）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2457","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿接种卡介苗的部位是？","options":["左上臂三角肌下端皮内","右上臂皮下","大腿肌肉","臀部皮下"],"answer":0,"explanation":"卡介苗接种于左上臂三角肌下端皮内（0.1ml），8-12周后做PPD试验验证。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2458","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，乙肝疫苗的接种时间是？","options":["8个月","出生、3个月、6个月","2、3、4个月","0、1、6个月"],"answer":3,"explanation":"乙肝疫苗：0（出生24小时内）、1、6个月各1针。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2459","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，脊髓灰质炎疫苗的接种时间是？","options":["2、3、4个月（口服糖丸）","出生时","6个月","1岁"],"answer":0,"explanation":"脊灰疫苗：2、3、4个月各口服1次（糖丸），4岁加强。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2460","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，百白破疫苗的接种时间是？","options":["2个月","出生时","3、4、5个月","1岁"],"answer":2,"explanation":"百白破三联疫苗：3、4、5个月各1针，18-24个月加强。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2461","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，麻疹疫苗的接种时间是？","options":["8个月","出生时","6个月","2岁"],"answer":0,"explanation":"麻疹减毒活疫苗：8个月初种，18-24个月复种。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2462","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，卡介苗的接种时间是？","options":["6个月","2个月","出生时","1岁"],"answer":2,"explanation":"卡介苗在出生时（24小时内）接种。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2463","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿计划免疫中，乙脑疫苗的接种时间是？","options":["3个月","出生时","8个月（灭活疫苗初种2针）","6个月"],"answer":2,"explanation":"乙脑灭活疫苗：8个月初种2针（间隔7-10天），2岁、6岁加强。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2464","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻病的治疗原则不包括？","options":["液体疗法","调整饮食","立即使用止泻药（强力止泻）","合理用药"],"answer":2,"explanation":"小儿腹泻治疗：调整饮食、液体疗法（核心）、合理用药、微生态制剂；不宜强力止泻（毒素滞留）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2465","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎的护理措施不包括？","options":["大量喂食（避免呛咳）","保持呼吸道通畅","定时翻身拍背","室内空气流通"],"answer":0,"explanation":"肺炎患儿应少量多次喂食，避免呛咳加重；保持气道通畅、拍背排痰。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2466","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿贫血的常见类型是？","options":["再生障碍性贫血","营养性缺铁性贫血","溶血性贫血","地中海贫血（地区性）"],"answer":1,"explanation":"小儿贫血以营养性缺铁性贫血最常见（6个月-2岁高发）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2467","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿缺铁性贫血的主要原因是？","options":["慢性失血","铁摄入不足（辅食添加不及时）","吸收障碍（成人）","溶血"],"answer":1,"explanation":"婴幼儿缺铁性贫血主要因铁摄入不足（未及时添加含铁辅食）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2468","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿缺铁性贫血的预防措施是？","options":["及时添加含铁辅食（4-6个月起）","补充维生素C（唯一）","输血","补钙"],"answer":0,"explanation":"预防：母乳喂养、4-6个月及时添加含铁辅食（强化铁米粉、蛋黄、肝泥等）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2469","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿维生素D缺乏的预防措施是？","options":["不干预","出生时大量补充","仅靠食物","生后数天开始补充维生素D 400IU/日"],"answer":3,"explanation":"预防佝偻病：生后数天开始每日维生素D 400IU（早产儿加倍），多晒太阳。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2470","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿肺炎合并心衰的紧急处理是？","options":["立即手术","强心（地高辛）、利尿、镇静、吸氧","抗生素加量","补液"],"answer":1,"explanation":"肺炎合并心衰：吸氧、镇静、强心（地高辛）、利尿、扩血管。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2471","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻脱水伴循环不良（重度）时，扩容阶段用？","options":["缓慢滴注","2:1等张含钠液20ml/kg，30-60分钟内静脉输入","口服补液","仅用生理盐水"],"answer":1,"explanation":"重度脱水扩容：2:1等张含钠液（或生理盐水）20ml/kg，30-60分钟快速输入。","exam":"医疗编","__sub":"临床常见病","diff":3,"id":"yl-2472","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿腹泻口服补液盐（ORS）适用于？","options":["肠梗阻","重度脱水","频繁呕吐者","轻中度脱水无呕吐者"],"answer":3,"explanation":"ORS适用于轻中度脱水、无严重呕吐者；重度脱水或呕吐严重者静脉补液。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2473","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿生理性腹泻的特点是？","options":["大便次数增多但生长发育正常、无需特殊治疗","伴发热","体重下降","需要抗生素"],"answer":0,"explanation":"生理性腹泻：母乳喂养儿大便次数多（6-10次/日）但生长发育正常，添加辅食后好转。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2474","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿脐炎的病原体主要是？","options":["病毒","大肠埃希菌（唯一）","厌氧菌（唯一）","金黄色葡萄球菌"],"answer":3,"explanation":"新生儿脐炎以金黄色葡萄球菌最常见，表现为脐部红肿、脓性分泌物。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2475","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿乳腺肿大和假月经的原因是？","options":["母体雌激素影响（生后中断）","感染","肿瘤","内分泌疾病"],"answer":0,"explanation":"新生儿受母体雌激素影响，可有乳腺肿大（2-3周消退）、阴道少量出血（假月经）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2476","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"新生儿生理性体重下降的幅度是？","options":["不下降","下降20%","出生后3-4天下降6-9%，7-10天恢复","下降50%"],"answer":2,"explanation":"新生儿生理性体重下降：3-4天最低（下降6-9%），7-10天恢复出生体重。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2477","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"早产儿是指？","options":["胎龄<40周","胎龄<37周出生的新生儿","胎龄>42周","体重<2500g"],"answer":1,"explanation":"早产儿：胎龄<37周；过期产儿≥42周；低出生体重儿<2500g。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2478","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"早产儿保暖的适宜温度（中性温度）是？","options":["根据体重调节（一般32-35℃暖箱）","固定26℃","固定40℃","室温即可"],"answer":0,"explanation":"早产儿中性温度根据体重和日龄调节（体重越低、日龄越小，所需温度越高）。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2479","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"小儿惊厥最常见的病因是？","options":["代谢异常","癫痫","颅内感染","高热惊厥"],"answer":3,"explanation":"小儿惊厥以高热惊厥最常见（6个月-5岁）。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2480","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"为病人测量脉搏时，首选的动脉是","options":["肱动脉","桡动脉","颈动脉","股动脉"],"answer":1,"explanation":"桡动脉表浅、易触及且不影响病人休息，是测量脉搏的首选部位。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2481","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"正常成人安静状态下的呼吸频率为","options":["28～32次/分","10～14次/分","22～26次/分","16～20次/分"],"answer":3,"explanation":"正常成人安静状态下呼吸频率为16～20次/分，节律均匀。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2482","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测量呼吸时护士的手仍置于病人脉搏部位是为了","options":["判断脉搏是否规律","转移病人注意力，避免其刻意控制呼吸","测量脉搏与呼吸的比例","防止病人躁动"],"answer":1,"explanation":"呼吸受意识控制，护士手留于诊脉部位可转移病人注意，获得真实呼吸频率。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2483","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"体温上升期病人的表现为","options":["畏寒、皮肤苍白、无汗","皮肤潮红、灼热","大量出汗","脉搏细速、血压下降"],"answer":0,"explanation":"体温上升期产热增加、散热减少，表现为畏寒、寒战、皮肤苍白、干燥无汗。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2484","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"高热病人退热期大量出汗时应特别警惕","options":["心律失常","过敏反应","虚脱（低血容量性休克）","脑水肿"],"answer":2,"explanation":"退热期大量出汗丢失体液，可致血容量不足，应警惕虚脱，及时补充水分和电解质。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2485","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测量口腔温度的适宜时间为","options":["5分钟","1分钟","3分钟","10分钟"],"answer":2,"explanation":"口温测量需3分钟，腋温需10分钟，肛温需3分钟。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2486","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"不宜测口温的病人是","options":["术后恢复期者","发热者","口鼻手术者","高血压病人"],"answer":2,"explanation":"口鼻手术、呼吸困难、昏迷、婴幼儿等不宜测口温，以免咬碎体温计或影响测量。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2487","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"水银体温计不慎被咬碎，应首先","options":["立即口服大量牛奶或蛋清","催吐","洗胃","服用泻药"],"answer":0,"explanation":"误服水银后可口服牛奶、蛋清等保护胃黏膜，并观察，金属汞不易吸收。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2488","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"血压测量的正确方法是","options":["袖带下缘距肘窝5cm以上","袖带下缘距肘窝2～3cm","袖带缠于肘窝处","袖带过紧不影响结果"],"answer":1,"explanation":"袖带下缘距肘窝2～3cm，松紧以能插入一指为宜。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2489","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"测血压时袖带过松会导致","options":["测得血压偏高","测得血压偏低","血压不变","测不出血压"],"answer":0,"explanation":"袖带过松需充气更多压力才能阻断血流，测得血压偏高。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2490","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"成人无菌注射前皮肤消毒常用消毒剂","options":["0.5%碘伏","75%乙醇","3%过氧化氢","0.1%苯扎溴铵"],"answer":0,"explanation":"注射部位皮肤消毒常用0.5%碘伏，消毒两遍，待干后注射。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2491","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌持物钳的正确使用方法是","options":["钳端向下，不可倒转向上","钳端向上","浸泡在消毒液中的部分不限","可夹取无菌物品换药后继续使用"],"answer":0,"explanation":"无菌持物钳使用时保持钳端向下，防止消毒液倒流污染钳端。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2492","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌包打开后未用完，有效期为","options":["4小时","24小时","7天","2小时"],"answer":1,"explanation":"无菌包打开后剩余物品有效期为24小时；铺好的无菌盘有效期为4小时。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2493","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"无菌盘铺好后有效期为","options":["7天","24小时","12小时","4小时"],"answer":3,"explanation":"铺好的无菌盘应在4小时内使用，超过时间视为污染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2494","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"已开启的无菌溶液瓶内剩余溶液，有效期不超过","options":["7天","4小时","48小时","24小时"],"answer":3,"explanation":"开启的无菌溶液应在4小时内用完；剩余溶液标注开启时间，超过24小时不得使用。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2495","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"取用无菌溶液时，正确的做法是","options":["先核对瓶签再检查溶液性质","直接倒入无菌容器","手触及瓶口","瓶塞内面朝下放置"],"answer":0,"explanation":"取无菌溶液应先核对瓶签、检查溶液有无浑浊沉淀，瓶塞内面朝上放置，手不可触及瓶口。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2496","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"戴无菌手套时，正确的做法是","options":["脱手套时先撕破","手可低于腰部","手套外面可触及皮肤","戴好手套的手保持在腰以上视线范围内"],"answer":3,"explanation":"戴无菌手套后双手应保持在腰部以上、视线范围内，避免污染。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2497","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"脱无菌手套的正确方法是","options":["用水冲洗后脱","直接撕下","先洗手后脱","手套外面相互捏脱，勿使手套外面触及皮肤"],"answer":3,"explanation":"脱手套应从手套口翻转脱下，避免手套外面（污染面）触及皮肤。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2498","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"皮下注射常选部位不包括","options":["上臂三角肌下缘","腹部","大腿外侧","足底"],"answer":0,"explanation":"皮下注射常选上臂三角肌下缘、腹部、后背、大腿外侧等，足底无皮下组织不宜注射。","exam":"医疗编","__sub":"临床常见病","diff":1,"id":"yl-2499","_shard":"qk-yiliao-04"},{"module":"yiliao","prompt":"臀大肌注射连线定位法正确的是","options":["外下1/3处","内上1/3处","髂前上棘与尾骨连线的外上1/3处","内下1/3处"],"answer":2,"explanation":"臀大肌注射连线法：取髂前上棘与尾骨连线的外上1/3处为注射区。","exam":"医疗编","__sub":"临床常见病","diff":2,"id":"yl-2500","_shard":"qk-yiliao-04"}]);